      description: 'Deux suites : « alors » si la condition est vraie, « sinon ». La condition lit status, time, body.chemin, headers.nom, env.nom, collection.nom, local.nom.',
      left: [FLOW], right: [{ ...FLOW, name: 'alors' }, { ...FLOW, name: 'sinon' }],
      fields: { cond: { kind: 'expr', label: 'Condition', default: { eq: [{ var: 'status' }, 200] }, vars: ['status', 'time', 'body', 'headers', 'env', 'collection', 'globals', 'local'] } },
      faces: { left: '#F4E9D2', right: '#F4E9D2' },
      title: (api) => { const e = api.domino.fields.cond; try { return `Si ${typeof e === 'string' ? e : D.Expr.text(e)}`; } catch (_) { return 'Si'; } },
      run: (rc) => {
        const ex = rc.inputs[0] || {}, r = ex.response || {};
        const E = (wsOf(rc).language && wsOf(rc).language.exprDialect) || D.Expr;
        const cond = typeof rc.node.fields.cond === 'string' ? E.parse(rc.node.fields.cond) : rc.node.fields.cond;
        const scope = { status: r.status, time: r.ms, body: r.json, headers: r.headers, env: rc.rootCtx.get('env') || {}, collection: rc.rootCtx.get('collection') || {}, globals: rc.rootCtx.get('globals') || {}, local: rc.ctx.get('local') || {} };
        const yes = !!E.evaluate(cond, scope);
        rc.report('tnr.if', { status: 'info', summary: `${yes ? 'vrai → alors' : 'faux → sinon'}` });
        return yes ? [ex, undefined] : [undefined, ex];
      },
