      validate: (api) => { const name = api.domino.fields.scenario; const ws = api.workspace; return !name || [...ws.nodes.values()].some((n) => n.type === 'tnr.scenario' && n.fields.name === name) ? [] : [{ level: 'error', code: 'tnr.call', message: `Aucun scénario « ${name} » dans la campagne.` }]; },
