/*!
 * Démo · Éditeur de circuit logique
 * Une chaîne de neuf portes (NON, ET, OU, OU exclusif, NON-ET, NON-OU…) de l'entrée A jusqu'à la LED.
 * Chaque porte reçoit son premier signal de la pierre précédente et le second d'une adjacente haute.
 * Mode direct : changer un signal dans le contexte relance l'évaluation.
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const bit = (v) => (v ? 1 : 0);

  const types = [
    { name: 'bit', label: 'Signal', color: '#151718', description: 'Un signal logique : 0 ou 1. Points noirs, comme un vrai domino.' },
  ];
  const gate = (type, name, fn, sym, left = 2) => ({
    type, name, category: 'Portes', description: `${name} : ${sym}`,
    left: Array.from({ length: left }, (_, i) => ({ name: left === 1 ? 'a' : 'ab'[i], type: 'bit' })),
    right: [{ name: 's', type: 'bit' }],
    run: (rc) => [bit(fn(...rc.inputs.map(bit)))],
  });

  const dominos = [
    {
      type: 'logic.in', name: 'Entrée', category: 'Entrées',
      description: 'Source (0 | 1) : lit son signal dans le contexte (signals.A…).',
      right: [{ name: 's', type: 'bit' }],
      fields: { name: { kind: 'select', label: 'Signal', options: ['A', 'B', 'C', 'D'], default: 'A', bindable: false } },
      title: (api) => api.field('name'),
      run: (rc) => [bit(rc.ctx.get(`signals.${rc.fields.name}`))],
    },
    gate('logic.not', 'NON', (a) => !a, '¬a', 1),
    gate('logic.and', 'ET', (a, b) => a && b, 'a ∧ b'),
    gate('logic.or', 'OU', (a, b) => a || b, 'a ∨ b'),
    gate('logic.xor', 'OU exclusif', (a, b) => a !== b, 'a ⊕ b'),
    gate('logic.nand', 'NON-ET', (a, b) => !(a && b), '¬(a ∧ b)'),
    gate('logic.nor', 'NON-OU', (a, b) => !(a || b), '¬(a ∨ b)'),
    {
      type: 'logic.led', name: 'LED', category: 'Sorties',
      description: 'Terminale (1 | 0) : s’allume quand elle reçoit 1.',
      left: [{ name: 'a', type: 'bit' }],
      run: (rc) => { const v = bit(rc.inputs[0]); rc.ctx.set('outputs.LED', v); if (!rc.silent) rc.node.state.tint = v ? '#FFE07A' : '#E9E6DC'; return []; },
    },
    {
      type: 'logic.probe', name: 'Sonde', category: 'Mesure',
      description: 'Terminale : en adjacente basse, elle mesure la sortie d’une porte.',
      left: [{ name: 'a', type: 'bit' }],
      fields: { name: { kind: 'text', label: 'Nom', default: 'P1', bindable: false } },
      title: (api) => `Sonde ${api.field('name')}`,
      run: (rc) => { rc.ctx.set(`probes.${rc.fields.name}`, bit(rc.inputs[0])); return []; },
    },
  ];

  const IN = (id, name) => ({ id, type: 'logic.in', fields: { name } });
  const top = (dom) => [{ pip: 1, domino: dom }];
  // A → NON → ET(B) → OU(C) → OU-X(D) → NON-ET(NON(B)) → NON-OU(A) → NON → OU(C) → ET(D) → LED : neuf niveaux de portes.
  const levels = [
    { id: 'g1', type: 'logic.not' },
    { id: 'g2', type: 'logic.and', top: top(IN('i2', 'B')) },
    { id: 'g3', type: 'logic.or', top: top(IN('i3', 'C')) },
    { id: 'g4', type: 'logic.xor', top: top(IN('i4', 'D')), bottom: [{ pip: 0, domino: { id: 'p1', type: 'logic.probe', fields: { name: 'P1' } } }] },
    { id: 'g5', type: 'logic.nand', top: top({ id: 'n5', type: 'logic.not', top: [{ pip: 0, domino: IN('i5', 'B') }] }) },
    { id: 'g6', type: 'logic.nor', top: top(IN('i6', 'A')), bottom: [{ pip: 0, domino: { id: 'p2', type: 'logic.probe', fields: { name: 'P2' } } }] },
    { id: 'g7', type: 'logic.not' },
    { id: 'g8', type: 'logic.or', top: top(IN('i8', 'C')) },
    { id: 'g9', type: 'logic.and', top: top(IN('i9', 'D')) },
    { id: 'led', type: 'logic.led' },
  ];
  let chain = null;
  for (const l of levels.reverse()) chain = { ...l, ...(chain ? { next: [{ pip: 0, domino: chain }] } : {}) };
  const project = {
    format: 'kantoaplo.domino', version: 1,
    editor: { id: 'circuit', name: 'Éditeur de circuit' },
    name: 'Logique à neuf niveaux',
    context: { signals: { A: true, B: false, C: true, D: true }, outputs: { LED: 0 }, probes: {} },
    parties: [{ id: 'main', name: 'Circuit', dominos: [{ ...IN('i1', 'A'), next: [{ pip: 0, domino: chain }] }] }],
  };

  // ---------------------------------------------------------------------------
  // Générateurs : expression booléenne et Verilog, depuis le JSON.
  // ---------------------------------------------------------------------------
  const OPS = { 'logic.and': ['∧', '&'], 'logic.or': ['∨', '|'], 'logic.xor': ['⊕', '^'], 'logic.nand': ['∧', '&', true], 'logic.nor': ['∨', '|', true] };
  const exprGen = (style) => {
    const g = new D.Generator(style, style === 'verilog' ? { label: 'Verilog', extension: 'v' } : { label: 'Expression', extension: 'txt' });
    const NOT = style === 'verilog' ? '~' : '¬';
    // Valeur d'une pierre : son entrée 0 vient de la précédente (ou d'une adjacente), son entrée 1 d'une adjacente haute.
    const value = (n, incoming) => {
      if (n.type === 'logic.in') return style === 'verilog' ? n.fields.name.toLowerCase() : n.fields.name;
      const a = incoming || (g.top(n, 0)[0] ? value(g.top(n, 0)[0]) : '0');
      if (n.type === 'logic.not') return `${NOT}${/^[\w¬~]+$/.test(a) ? a : `(${a})`}`;
      const op = OPS[n.type];
      if (!op) return a;
      const b = g.top(n, 1)[0] ? value(g.top(n, 1)[0]) : '0';
      const e = `${a} ${style === 'verilog' ? op[1] : op[0]} ${b}`;
      return op[2] ? `${NOT}(${e})` : `(${e})`;
    };
    g.on('project', (json) => {
      const outs = [];
      for (const p of json.parties) for (const head of p.dominos) {
        let acc = null;
        for (let n = head; n; n = g.next(n, 0)) {
          if (n.type === 'logic.led') outs.push(['LED', acc]);
          else acc = value(n, acc && n.type !== 'logic.in' ? acc : null);
          for (const b of g.bottom(n)) if (b.type === 'logic.probe') outs.push([b.fields.name, acc]);
        }
      }
      if (style === 'verilog') {
        return [`module logique (input a, b, c, d, output led${outs.filter(([k]) => k !== 'LED').map(([k]) => `, output ${k.toLowerCase()}`).join('')});`, ...outs.map(([k, e]) => `  assign ${k.toLowerCase()} = ${e};`), 'endmodule'].join('\n');
      }
      return outs.map(([k, e]) => `${k} = ${e}`).join('\n\n');
    });
    return g;
  };

  // ---------------------------------------------------------------------------
  // Onglet « Banc de test » : interrupteurs, LED et table de vérité calculée par le moteur.
  // ---------------------------------------------------------------------------
  async function truthTable(ed) {
    const rows = [];
    for (let m = 0; m < 16; m++) {
      const s = { A: !!(m & 8), B: !!(m & 4), C: !!(m & 2), D: !!(m & 1) };
      const r = await ed.runtime.run({ silent: true, context: { signals: s, outputs: { LED: 0 }, probes: {} } });
      rows.push({ s, led: r.context.get('outputs.LED'), p1: r.context.get('probes.P1'), p2: r.context.get('probes.P2'), ok: r.ok });
    }
    return rows;
  }

  D.packs.circuit = {
    id: 'circuit', name: 'Éditeur de circuit', color: '#E5484D',
    description: 'Neuf niveaux de portes logiques jusqu’à la LED, évalués en direct.',
    types, dominos, project, context: project.context,
    generators: [exprGen('expr'), exprGen('verilog')],
    options: { table: 1250, live: true, runDelay: 120 },
    inspector: {
      tabs: [{
        id: 'bench', title: 'Banc de test',
        help: 'Exemple d’onglet propre à un laboratoire : interrupteurs, LED et table de vérité',
        onEvent: (ev) => ['context', 'change', 'load', 'run:end'].includes(ev.type),
        render: (el, insp) => {
          const ws = insp.ws, ed = insp.ed;
          const sig = ws.context.get('signals') || {};
          const led = ws.context.get('outputs.LED');
          el.innerHTML = `<div class="dk-split"><div class="dk-pane"><div class="dk-toolbar"><b style="font-size:12px">Interrupteurs</b><span style="color:var(--ink-3);font-size:11.5px">Ils écrivent dans le contexte (<code>signals.*</code>) ; le mode direct relance le circuit.</span></div>
            <div style="padding:12px;display:flex;gap:10px;flex-wrap:wrap;align-items:center">${['A', 'B', 'C', 'D'].map((k) => `<button class="dk-btn${sig[k] ? ' on' : ''}" data-sig="${k}" aria-pressed="${!!sig[k]}" style="min-width:64px;justify-content:center;font-family:var(--f-mono)">${k} = ${sig[k] ? 1 : 0}</button>`).join('')}
            <span style="display:inline-flex;align-items:center;gap:8px;margin-left:8px;font-weight:600"><i style="width:22px;height:22px;border-radius:50%;display:inline-block;background:${led ? '#FFD84A' : 'var(--line)'};box-shadow:${led ? '0 0 14px #FFD84A' : 'none'};border:1px solid var(--line-strong)"></i>LED = ${led ? 1 : 0}</span></div>
            <p style="margin:0 12px 12px;color:var(--ink-3);font-size:11.5px">Sondes : P1 = ${ws.context.get('probes.P1') ?? '—'}, P2 = ${ws.context.get('probes.P2') ?? '—'}. Ce banc est un onglet ajouté par le pack « circuit » : un laboratoire y mettrait ses propres mesures.</p></div>
            <div class="dk-pane tt"><p class="dk-empty">Calcul de la table de vérité…</p></div></div>`;
          el.querySelectorAll('[data-sig]').forEach((b) => b.addEventListener('click', () => ws.context.set(`signals.${b.dataset.sig}`, !sig[b.dataset.sig])));
          truthTable(ed).then((rows) => {
            const cur = (r) => ['A', 'B', 'C', 'D'].every((k) => !!sig[k] === r.s[k]);
            const box = el.querySelector('.tt');
            if (!box) return;
            box.innerHTML = `<table class="dk-table"><thead><tr><th>A</th><th>B</th><th>C</th><th>D</th><th>P1</th><th>P2</th><th>LED</th></tr></thead><tbody>${rows.map((r) => `<tr style="${cur(r) ? 'background:var(--brass-soft);font-weight:600' : ''}">${['A', 'B', 'C', 'D'].map((k) => `<td>${r.s[k] ? 1 : 0}</td>`).join('')}<td>${r.p1}</td><td>${r.p2}</td><td>${r.led ? '<b style="color:var(--warn)">● 1</b>' : '○ 0'}</td></tr>`).join('')}</tbody></table>`;
          });
        },
      }],
    },
  };
})(typeof globalThis !== 'undefined' ? globalThis : window);
