/*!
 * Langage · Atelier
 * Un langage pour écrire des langages. Chaque domino ajoute un morceau du langage en construction :
 * son nom et sa règle de chaîne, ses types de points, ses pierres (faces, champ, code), ses règles.
 * Le générateur « Langage (JSON) » rend un fichier que Domino.language() charge tel quel ;
 * l'onglet « Aperçu » crée l'éditeur de ce langage, en direct, à chaque modification.
 */
(function (root) {
  'use strict';
  const D = root.Domino;

  const types = [
    { name: 'langage', label: 'Langage', color: '#B8893B', description: 'Le langage en construction : il passe de pierre en pierre et grandit.' },
  ];
  const slug = (s) => String(s || 'x').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'x';
  const list = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);
  const ON = { fil: 'wire', suite: 'next', haute: 'top', basse: 'bottom' };
  const parseValue = (v) => { if (v === '' || v == null) return undefined; const n = Number(v); return Number.isNaN(n) ? v : n; };

  /** Le langage décrit par une suite de pierres de l'Atelier ({ type, fields }, dans l'ordre de la chaîne). */
  function build(chain) {
    const spec = { format: 'kantoaplo.language', version: 1, id: 'langage', name: 'Langage', color: '#3B7DDD', types: [], dominos: [], rules: { chain: 'types', wires: true, list: [] } };
    for (const n of chain) {
      const f = n.fields || {};
      if (n.type === 'at.lang') Object.assign(spec, { id: slug(f.id || f.name), name: f.name || 'Langage', color: f.color || '#3B7DDD', rules: { ...spec.rules, chain: f.rule || 'types', wires: f.wires !== false } });
      else if (n.type === 'at.type') spec.types.push(D.compact({ name: slug(f.name), label: f.label || f.name, color: f.color || '#151718' }));
      else if (n.type === 'at.stone') {
        const def = D.compact({
          type: slug(f.name), name: f.name, category: f.category || 'Pierres',
          left: list(f.left).map((t) => ({ name: t, type: slug(t) })),
          right: list(f.right).map((t) => ({ name: t, type: slug(t) })),
          fields: f.value !== '' && f.value != null ? { valeur: { label: 'Valeur', default: parseValue(f.value) } } : undefined,
          faces: f.face ? { left: f.face, right: f.face } : undefined,
          code: f.code ? { run: f.code } : undefined,
        });
        // Une face vide est un zéro : il faut le dire au moteur.
        def.left = def.left || []; def.right = def.right || [];
        spec.dominos.push(def);
      } else if (n.type === 'at.rule') spec.rules.list.push(D.compact({ id: slug(f.id), on: ON[f.on] || 'wire', when: f.when, message: f.message }));
    }
    return spec;
  }

  const step = (type, name, fields, title, description) => ({
    type, name, category: 'Atelier', description,
    left: [{ name: 'langage', type: 'langage' }], right: [{ name: 'langage', type: 'langage' }],
    fields, title,
    run: (rc) => [mergeInto(D.clone(rc.inputs[0] || build([])), { type, fields: rc.fields })],
  });
  const mergeInto = (spec, node) => {
    const b = build([{ type: 'at.lang', fields: { name: spec.name, id: spec.id, rule: spec.rules.chain, wires: spec.rules.wires, color: spec.color } }, node]);
    if (node.type === 'at.type') spec.types.push(...b.types);
    if (node.type === 'at.stone') spec.dominos.push(...b.dominos);
    if (node.type === 'at.rule') spec.rules.list.push(...b.rules.list);
    return spec;
  };

  const dominos = [
    {
      type: 'at.lang', name: 'Langage', category: 'Atelier', kind: 'tête',
      description: 'Commence un langage : son nom, sa couleur, sa règle de chaîne, ses fils.',
      right: [{ name: 'langage', type: 'langage' }],
      fields: {
        name: { kind: 'text', label: 'Nom', default: 'Mon langage', bindable: false },
        id: { kind: 'text', label: 'Identifiant', default: '', bindable: false },
        color: { kind: 'color', label: 'Couleur', default: '#3B7DDD', bindable: false },
        rule: { kind: 'select', label: 'Règle de chaîne', options: [['types', 'couleurs des points'], ['count', 'même nombre (le jeu)'], ['both', 'les deux']], default: 'types', bindable: false },
        wires: { kind: 'toggle', label: 'Fils permis', default: true, bindable: false },
      },
      title: (api) => `Langage « ${api.raw('name')} »`,
      run: (rc) => [build([{ type: 'at.lang', fields: rc.fields }])],
    },
    step('at.type', 'Type de point', {
      name: { kind: 'text', label: 'Nom', default: 'nombre', bindable: false },
      label: { kind: 'text', label: 'Libellé', default: 'Nombre', bindable: false },
      color: { kind: 'color', label: 'Couleur', default: '#3B7DDD', bindable: false },
    }, (api) => `Type « ${api.raw('label') || api.raw('name')} »`, 'Ajoute une couleur de point : un type de connexion.'),
    step('at.stone', 'Pierre', {
      name: { kind: 'text', label: 'Nom', default: 'Pierre', bindable: false },
      category: { kind: 'text', label: 'Catégorie', default: 'Pierres', bindable: false },
      left: { kind: 'text', label: 'Gauche (types)', default: 'nombre', bindable: false, help: 'Un point par type, séparés par des virgules. Vide : zéro.' },
      right: { kind: 'text', label: 'Droite (types)', default: 'nombre', bindable: false },
      value: { kind: 'text', label: 'Champ « valeur »', default: '', bindable: false, help: 'Valeur par défaut d’un champ « valeur » (vide : pas de champ).' },
      face: { kind: 'color', label: 'Façade', default: '', bindable: false },
      code: { kind: 'code', label: 'Code de run()', default: 'return [inputs[0]];', bindable: false, help: 'Reçoit inputs, fields, ctx, log. Rend les sorties.' },
    }, (api) => `${api.raw('name')} ${list(api.raw('left')).length}|${list(api.raw('right')).length}`, 'Ajoute une pierre : ses faces (combien de points, de quels types), son champ, son code.'),
    step('at.rule', 'Règle', {
      id: { kind: 'text', label: 'Nom', default: 'ma-règle', bindable: false },
      on: { kind: 'select', label: 'S’applique à', options: [['fil', 'un fil'], ['suite', 'une suite'], ['haute', 'une adjacente haute'], ['basse', 'une adjacente basse']], default: 'fil', bindable: false },
      when: { kind: 'code', label: 'Refuser si', default: "q.child.type === 'x'", bindable: false, help: 'Expression JavaScript : q.parent, q.child (api), q.via, q.pip.' },
      message: { kind: 'text', label: 'Message', default: 'Refusé.', bindable: false },
    }, (api) => `Règle « ${api.raw('id')} »`, 'Ajoute une règle d’assemblage nommée, avec son message.'),
    {
      type: 'at.publish', name: 'Publier', category: 'Atelier', kind: 'fin',
      description: 'Termine le langage : il est écrit dans le contexte (« langage »).',
      left: [{ name: 'langage', type: 'langage' }],
      run: (rc) => {
        const spec = rc.inputs[0];
        rc.ctx.set('langage', spec);
        rc.log('info', `langage « ${spec.name} » : ${D.plural(spec.types.length, 'type')}, ${D.plural(spec.dominos.length, 'pierre')}, ${D.plural(spec.rules.list.length, 'règle')}, règle de chaîne « ${spec.rules.chain} »`);
        return [];
      },
    },
  ];

  // ---------------------------------------------------------------------------
  // « Calculette », un langage écrit avec 11 dominos.
  // ---------------------------------------------------------------------------
  const chainOf = (...nodes) => { let head = null; for (const n of nodes.reverse()) head = { ...n, ...(head ? { next: [{ pip: 0, domino: head }] } : {}) }; return head; };
  const project = {
    format: 'kantoaplo.domino', version: 2,
    editor: { id: 'atelier', name: 'Atelier' },
    name: 'Calculette',
    context: {},
    parties: [{
      id: 'main', kind: 'main', name: 'Calculette',
      dominos: [{ ...chainOf(
        { id: 'l', type: 'at.lang', fields: { name: 'Calculette', id: 'calculette', color: '#3B7DDD', rule: 'count', wires: true } },
        { id: 't1', type: 'at.type', fields: { name: 'nombre', label: 'Nombre', color: '#3B7DDD' } },
        { id: 't2', type: 'at.type', fields: { name: 'texte', label: 'Texte', color: '#38A169' } },
        { id: 's1', type: 'at.stone', fields: { name: 'Nombre', category: 'Valeurs', left: '', right: 'nombre', value: '7', face: '#EAF1FB', code: 'return [Number(fields.valeur)];' } },
        { id: 's2', type: 'at.stone', fields: { name: 'Doubler', category: 'Calculs', left: 'nombre', right: 'nombre', value: '', face: '', code: 'return [inputs[0] * 2];' } },
        { id: 's3', type: 'at.stone', fields: { name: 'Ajouter', category: 'Calculs', left: 'nombre, nombre', right: 'nombre', value: '', face: '', code: 'return [(inputs[0] ?? 0) + (inputs[1] ?? 0)];' } },
        { id: 's4', type: 'at.stone', fields: { name: 'Écrire', category: 'Textes', left: 'nombre', right: 'texte', value: '', face: '', code: 'return [`= ${inputs[0]}`];' } },
        { id: 's5', type: 'at.stone', fields: { name: 'Afficher', category: 'Textes', left: 'texte', right: '', value: '', face: '#E3F1E7', code: "log('info', inputs[0]); ctx.set('écran', inputs[0]); return [];" } },
        { id: 'r1', type: 'at.rule', fields: { id: 'afficher-colle', on: 'fil', when: "q.child.type === 'afficher'", message: 'Afficher se colle au bout d’une chaîne : pas de fil.' } },
        { id: 'p', type: 'at.publish' },
      ), position: { x: 0, y: 40 } }],
    }],
  };

  // ---------------------------------------------------------------------------
  // Générateurs : le langage en JSON, et en module JavaScript prêt à charger.
  // ---------------------------------------------------------------------------
  const specOf = (json, g) => {
    const main = json.parties.find((p) => p.id === 'main');
    const head = (main.dominos || []).find((d) => d.type === 'at.lang');
    const chain = [];
    for (let n = head; n; n = g.next(n, 0)) chain.push(n);
    return build(chain);
  };
  const langJSON = new D.Generator('language', { label: 'Langage (JSON)', extension: 'json' }).on('project', (json, g) => JSON.stringify(specOf(json, g), null, 2));
  const langJS = new D.Generator('module', { label: 'Module JavaScript', extension: 'js' }).on('project', (json, g) => {
    const s = specOf(json, g);
    return `// Généré par l’Atelier Zeugma.\n// <script src="domino.*.js"> puis ce fichier, puis : Domino.create('#hôte', Domino.packs['${s.id}']);\n(Domino.packs = Domino.packs || {})['${s.id}'] = Domino.language(${JSON.stringify(s, null, 2)});\n`;
  });

  /** Un projet d'exemple pour l'aperçu : une pierre de chaque, collées quand la règle du langage le permet. */
  function sample(L) {
    const { ws } = L.instantiate(null);
    const placed = (L.dominos || []).map((d) => ws.create(d.type, { position: { x: 0, y: 0 } }));
    const head = placed.find((n) => !ws.pipsOf(n).left.length) || placed[0];
    if (!head) return D.Serializer.toJSON(ws);
    const used = new Set([head.id]);
    let cur = head;
    for (const n of placed) { if (used.has(n.id)) continue; if (ws.canConnect(cur.id, n.id).ok) { ws.connect(cur.id, n.id); used.add(n.id); cur = n; } }
    head.position = { x: 0, y: 40 };
    let i = 0;
    for (const n of placed) if (!used.has(n.id)) n.position = { x: i++ * 230, y: 300 };
    ws.name = L.name;
    ws.parties.get('main').name = `Essai de ${L.name}`;
    return D.Serializer.toJSON(ws);
  }

  // ---------------------------------------------------------------------------
  // Onglet « Aperçu » : l'éditeur du langage en construction, recréé à chaque modification.
  // ---------------------------------------------------------------------------
  const previews = new WeakMap();
  const previewTab = {
    id: 'preview', title: 'Aperçu',
    help: 'L’éditeur du langage décrit par ces dominos, créé en direct par Domino.create()',
    onEvent: (ev) => ['change', 'load'].includes(ev.type),
    render: (el, insp) => {
      const ed = insp.ed, e = insp.esc;
      let spec, L, err = null;
      try { spec = JSON.parse(ed.generate('language')); L = D.language({ ...spec, project: null }); L.createRegistry(); } catch (x) { err = x.message; }
      const old = previews.get(ed);
      if (old) { try { old.destroy(); } catch (_) { /* rien */ } previews.delete(ed); }
      el.innerHTML = `<div class="dk-pane" style="display:grid;grid-template-rows:auto minmax(0,1fr);height:100%"><div class="dk-toolbar"><b style="font-size:12px">${e(spec ? spec.name : 'Langage')}</b><span style="color:var(--ink-3);font-size:11.5px">${err ? `<span style="color:var(--err)">${e(err)}</span>` : `${D.plural(spec.types.length, 'type')} · ${D.plural(spec.dominos.length, 'pierre')} · règle « ${e(spec.rules.chain)} » · créé par <code>Domino.create(hôte, Domino.language(json))</code>`}</span><button class="dk-btn" data-big style="margin-left:auto">Agrandir</button><button class="dk-btn primary" data-run ${err ? 'disabled' : ''}>▶ Effet domino</button></div><div class="dk-preview-host" style="position:relative;min-height:340px"></div></div>`;
      el.querySelector('[data-big]').addEventListener('click', () => insp.maximize(!insp.state.max));
      if (err) return;
      const host = el.querySelector('.dk-preview-host');
      const L2 = D.language({ ...spec, project: sample(L) });
      const pv = D.create(host, L2, { inspector: false, coach: false, table: 1100 });
      previews.set(ed, pv);
      el.querySelector('[data-run]').addEventListener('click', () => pv.run());
    },
  };

  (D.packs = D.packs || {}).atelier = D.language({
    id: 'atelier', name: 'Atelier', color: '#B8893B',
    description: 'Un langage pour écrire des langages : chaque domino ajoute un type, une pierre ou une règle ; l’aperçu crée l’éditeur en direct.',
    types, dominos, project, context: {},
    semantics: (l, r, def, base) => ({ label: { source: 'Début', terminal: 'Fin', step: 'Ajout', value: 'Valeur' }[base.role] || base.label }),
    faces: {
      kinds: { tête: { left: '#F3E6CB', right: '#EBD3A2' }, fin: { left: '#EBD3A2', right: '#F3E6CB' } },
      legend: [{ label: 'Début et fin du langage', left: '#F3E6CB', right: '#EBD3A2' }],
    },
    rules: { chain: 'types', wires: false },
    generators: [langJSON, langJS],
    options: { table: 1500 },
    inspector: { tabs: [previewTab] },
  });
  // Pour d'autres outils : construire un langage depuis une suite de pierres, sans le moteur.
  D.packs.atelier.build = build;
  D.packs.atelier.sample = sample;
})(typeof globalThis !== 'undefined' ? globalThis : window);
