/*!
 * Langage · Raisonnement
 * Pas une ligne de code : une théorie. Chaque pierre est une idée, un appui, une objection, une réponse ;
 * les concepts sont déclarés une fois et cités par leur identifiant ; une objection peut être toute une
 * théorie, rangée dans une pierre et ouverte dans un onglet. L'effet domino mesure la solidité de la conclusion.
 * Pas de générateur : le document de modèle (onglet « Modèle ») est la sortie.
 */
(function (root) {
  'use strict';
  const D = root.Domino;

  const types = [
    { name: 'idée', label: 'Idée', color: '#6A5BDC', description: 'Un énoncé, avec sa force (0 à 1).' },
    { name: 'appui', label: 'Appui', color: '#38A169', description: 'Une preuve, une expérience, une source.' },
    { name: 'objection', label: 'Objection', color: '#E5484D', description: 'Ce qui affaiblit une conclusion.' },
    { name: 'concept', label: 'Concept', color: '#B8893B', description: 'Un concept défini une fois, cité partout.' },
  ];
  const pct = (x) => `${Math.round(x * 100)} %`;
  const clamp = (x) => Math.max(0, Math.min(1, Number(x) || 0));
  const strength = { kind: 'number', label: 'Force', default: 0.8, min: 0, max: 1, unit: '0 à 1', bindable: false };

  const dominos = [
    {
      type: 'r.thesis', name: 'Thèse', category: 'Idées', kind: 'thèse', represents: 'idée',
      description: 'Point de départ : un énoncé et la confiance qu’on lui accorde avant d’argumenter.',
      right: [{ name: 'idée', type: 'idée' }],
      fields: { text: { kind: 'textarea', label: 'Énoncé', default: 'Une thèse.', required: true }, force: { ...strength, label: 'Confiance de départ', default: 0.5 } },
      title: (api) => `« ${api.raw('text')} »`,
      run: (rc) => [{ text: rc.fields.text, force: clamp(rc.fields.force), trail: [rc.fields.text] }],
    },
    {
      type: 'r.premise', name: 'Prémisse', category: 'Idées', kind: 'prémisse', represents: 'argument',
      description: 'Un pas du raisonnement. Un appui (adjacente haute) le rend plus fort ; un concept cité dit de quoi l’on parle.',
      meaning: { left: 'l’idée qui précède, un appui, un concept', right: 'l’idée renforcée' },
      left: [{ name: 'idée', type: 'idée' }, { name: 'appui', type: 'appui', required: false }, { name: 'concept', type: 'concept', required: false }],
      right: [{ name: 'idée', type: 'idée' }],
      top: { max: 2 },
      fields: { text: { kind: 'textarea', label: 'Énoncé', default: 'Une prémisse.', required: true }, force: strength },
      title: (api) => `« ${api.raw('text')} »`,
      run: (rc) => {
        const [prev, appui, concept] = rc.inputs;
        const base = prev ? prev.force : 0.5, support = appui ? appui.poids : 0.5;
        // Une prémisse comble une part de ce qui manquait : sa force, multipliée par celle de son appui.
        const force = base + (1 - base) * clamp(rc.fields.force) * support;
        return [{ text: rc.fields.text, force, trail: [...((prev && prev.trail) || []), rc.fields.text], concepts: [...((prev && prev.concepts) || []), ...(concept ? [concept] : [])] }];
      },
    },
    {
      type: 'r.evidence', name: 'Appui', category: 'Appuis', kind: 'appui', represents: 'donnée',
      description: 'Une preuve ou une expérience, avec son poids. Elle se colle sur une prémisse (adjacente haute).',
      right: [{ name: 'appui', type: 'appui' }],
      fields: { source: { kind: 'text', label: 'Source', default: 'Une source', required: true }, poids: { ...strength, label: 'Poids' } },
      title: (api) => api.raw('source'),
      run: (rc) => [{ source: rc.fields.source, poids: clamp(rc.fields.poids) }],
    },
    {
      type: 'r.therefore', name: 'Donc', category: 'Idées', kind: 'prémisse', represents: 'argument',
      description: 'Réunit deux idées : la conclusion ne vaut pas plus que la plus faible.',
      left: [{ name: 'idée', type: 'idée' }, { name: 'et', type: 'idée' }], right: [{ name: 'idée', type: 'idée' }],
      run: (rc) => { const [a, b] = rc.inputs; return [{ text: 'donc', force: Math.min(a ? a.force : 0, b ? b.force : 0), trail: [...((a && a.trail) || []), ...((b && b.trail) || [])] }]; },
    },
    {
      type: 'r.objection', name: 'Objection', category: 'Objections', kind: 'objection', represents: 'argument',
      description: 'Transforme une idée adverse en objection : son poids dépend de la force de cette idée.',
      left: [{ name: 'idée adverse', type: 'idée' }], right: [{ name: 'objection', type: 'objection' }],
      fields: { text: { kind: 'textarea', label: 'Énoncé', default: 'Une objection.', required: true }, poids: { ...strength, label: 'Portée', default: 0.6 } },
      title: (api) => `✗ « ${api.raw('text')} »`,
      run: (rc) => { const a = rc.inputs[0]; return [{ text: rc.fields.text, poids: clamp(rc.fields.poids) * (a ? a.force : 1) }]; },
    },
    {
      type: 'r.reply', name: 'Réponse', category: 'Objections', kind: 'réponse', represents: 'argument',
      description: 'Répond à une objection : elle en atténue le poids.',
      left: [{ name: 'objection', type: 'objection' }], right: [{ name: 'objection', type: 'objection' }],
      fields: { text: { kind: 'textarea', label: 'Énoncé', default: 'Une réponse.', required: true }, attenuation: { ...strength, label: 'Atténuation', default: 0.5 } },
      title: (api) => `↺ « ${api.raw('text')} »`,
      run: (rc) => { const o = rc.inputs[0] || { poids: 0 }; return [{ ...o, poids: o.poids * (1 - clamp(rc.fields.attenuation)), réponse: rc.fields.text }]; },
    },
    {
      type: 'r.conclusion', name: 'Conclusion', category: 'Idées', kind: 'conclusion', represents: 'idée',
      description: 'Aboutissement : la force de l’idée, diminuée par chaque objection reçue (par des fils).',
      meaning: { left: 'l’idée, et toutes les objections (un fil chacune)' },
      left: [{ name: 'idée', type: 'idée' }, { name: 'objections', type: 'objection', multiple: true, required: false }],
      fields: { text: { kind: 'textarea', label: 'Énoncé', default: 'Une conclusion.', required: true } },
      title: (api) => `⟹ « ${api.raw('text')} »`,
      run: (rc) => {
        const [idea, objs] = rc.inputs;
        const list = [].concat(objs || []).filter(Boolean);
        const force = (idea ? idea.force : 0) * list.reduce((k, o) => k * (1 - o.poids), 1);
        const verdict = force >= 0.75 ? 'solide' : force >= 0.5 ? 'plutôt solide' : force >= 0.3 ? 'fragile' : 'intenable';
        rc.ctx.set('verdict', { conclusion: rc.fields.text, force: Math.round(force * 1000) / 1000, verdict, objections: list.map((o) => ({ text: o.text, poids: Math.round(o.poids * 1000) / 1000, réponse: o.réponse })), concepts: (idea && idea.concepts) || [] });
        rc.log('info', `« ${rc.fields.text} » : ${pct(force)} (${verdict})`);
        return [];
      },
    },
    {
      type: 'r.theory', name: 'Théorie', category: 'Théories', kind: 'théorie', represents: 'scénario',
      description: 'Toute une théorie dans une pierre : double-clic pour l’ouvrir dans un onglet. Elle rend l’idée qui sort de son « Résultat ».',
      right: [{ name: 'idée', type: 'idée' }],
      fields: { name: { kind: 'text', label: 'Nom', default: 'Une théorie', required: true } },
      inside: { kind: 'Théorie', template: [{ type: 'r.thesis', position: { x: 0, y: 0 }, next: [{ pip: 0, domino: { type: 'domino.exit', fields: { name: 'idée' } } }] }] },
      title: (api) => `▣ ${api.raw('name')}`,
      run: async (rc) => { const r = await rc.runPartie([]); return [r.idée || Object.values(r)[0]]; },
    },
  ];

  const project = {
    format: 'kantoaplo.domino', version: 2,
    editor: { id: 'raison', name: 'Raisonnement' },
    name: 'Le libre arbitre',
    context: {},
    parties: [
      {
        id: 'main', kind: 'main', name: 'Le libre arbitre',
        dominos: [
          {
            id: 'th', type: 'r.thesis', position: { x: 0, y: 140 }, fields: { text: 'Nous sommes libres', force: 0.5 },
            next: [{ pip: 0, domino: {
              id: 'p1', type: 'r.premise', fields: { text: 'Nous délibérons avant d’agir', force: 0.9 },
              top: [{ pip: 1, domino: { id: 'a1', type: 'r.evidence', fields: { source: 'L’expérience vécue', poids: 0.8 } } }, { pip: 2, domino: { id: 'k1', type: 'get.cDelib' } }],
              next: [{ pip: 0, domino: {
                id: 'p2', type: 'r.premise', fields: { text: 'Délibérer suppose plusieurs possibles', force: 0.85 },
                top: [{ pip: 2, domino: { id: 'k2', type: 'get.cLibre' } }],
                next: [{ pip: 0, domino: { id: 'co', type: 'r.conclusion', fields: { text: 'Notre volonté est libre' } } }],
              } }],
            } }],
          },
          {
            id: 'td', type: 'r.theory', position: { x: 0, y: 420 }, fields: { name: 'Le déterminisme causal' },
            note: 'Ouvrir la pierre : la théorie adverse, argumentée à part.',
            next: [{ pip: 0, domino: {
              id: 'ob', type: 'r.objection', fields: { text: 'Nos choix sont causés', poids: 0.6 },
              next: [{ pip: 0, domino: { id: 'rp', type: 'r.reply', fields: { text: 'Le compatibilisme : être libre, c’est agir selon ses raisons', attenuation: 0.5 } } }],
            } }],
          },
        ],
      },
      {
        id: 'decl', kind: 'declarations', name: 'Concepts',
        dominos: [
          { id: 'cLibre', type: 'decl.variable', position: { x: 0, y: 0 }, fields: { name: 'liberté', type: 'concept', initial: 'Pouvoir faire autrement que ce que l’on fait.', color: '#B8893B' } },
          { id: 'cDelib', type: 'decl.variable', position: { x: 260, y: 0 }, fields: { name: 'délibération', type: 'concept', initial: 'Peser des raisons avant de choisir.', color: '#B8893B' } },
        ],
      },
      {
        id: 'td', kind: 'component', owner: 'td', name: 'Le déterminisme causal',
        dominos: [{
          id: 'dt', type: 'r.thesis', position: { x: 0, y: 0 }, fields: { text: 'Tout événement a une cause', force: 0.7 },
          next: [{ pip: 0, domino: {
            id: 'dp', type: 'r.premise', fields: { text: 'Nos choix sont des événements', force: 0.8 },
            next: [{ pip: 0, domino: { id: 'dx', type: 'domino.exit', fields: { name: 'idée' } } }],
          } }],
        }],
      },
    ],
    wires: [{ id: 'f1', from: { domino: 'rp', pip: 0 }, to: { domino: 'co', pip: 1 }, label: 'objection' }],
  };

  // Onglet « Solidité » : la force de chaque idée au dernier passage, et le verdict.
  const tab = {
    id: 'solidite', title: 'Solidité',
    help: 'Exemple d’onglet propre au langage : la force de chaque idée et le verdict',
    onEvent: (ev) => ['run:end', 'load'].includes(ev.type),
    render: (el, insp) => {
      const ws = insp.ws, e = insp.esc, v = ws.context.get('verdict');
      const rows = [...ws.nodes.values()].filter((n) => n.state.lastRun && n.state.lastRun.outputs && n.state.lastRun.outputs[0] && typeof n.state.lastRun.outputs[0].force === 'number')
        .map((n) => ({ n, f: n.state.lastRun.outputs[0].force }));
      el.innerHTML = `<div class="dk-split"><div class="dk-pane"><div class="dk-toolbar"><b style="font-size:12px">Force de chaque idée</b><span style="color:var(--ink-3);font-size:11.5px">Lancez l’effet domino : chaque prémisse renforce, chaque objection affaiblit.</span></div>
        ${rows.length ? rows.map(({ n, f }) => `<div class="dk-wf ok"><span class="nm">${insp.link(n.id)}</span><span class="bar"><i style="left:0;width:${f * 100}%"></i></span><span class="ms">${pct(f)}</span></div>`).join('') : '<p class="dk-empty">Pas encore de passage.</p>'}</div>
        <div class="dk-pane"><div class="dk-toolbar"><b style="font-size:12px">Verdict</b></div>${v ? `<div style="padding:12px 14px;display:grid;gap:6px"><div style="font:650 16px var(--f-display)">« ${e(v.conclusion)} » : ${pct(v.force)}, ${e(v.verdict)}</div>${v.objections.map((o) => `<div style="color:var(--ink-2)">✗ ${e(o.text)} : poids ${pct(o.poids)}${o.réponse ? ` après la réponse « ${e(o.réponse)} »` : ''}</div>`).join('')}<div style="color:var(--ink-3);font-size:12px">Concepts cités : ${v.concepts.map(e).join(' · ') || '—'}</div></div>` : '<p class="dk-empty">—</p>'}</div></div>`;
      insp.wire(el);
    },
  };

  (D.packs = D.packs || {}).raison = D.language({
    id: 'raison', name: 'Raisonnement', color: '#9C4F96',
    description: 'Une théorie en dominos : idées, appuis, objections, réponses ; des concepts déclarés une fois ; une théorie adverse rangée dans une pierre.',
    types, dominos, project, context: {},
    semantics: (l, r, def, base) => ({ label: { source: 'Point de départ', step: 'Pas de raisonnement', terminal: 'Aboutissement', value: 'Donnée', free: 'Libre', declaration: 'Concept' }[base.role] }),
    faces: {
      kinds: { thèse: { left: '#EDE8FB', right: '#DCD3F5' }, conclusion: { left: '#DCD3F5', right: '#EDE8FB' }, objection: { left: '#FBE3E3', right: '#F6CACA' }, réponse: { left: '#F6CACA', right: '#E7F3EA' }, appui: { left: null, right: '#E3F1E7' }, théorie: { left: '#F1E9DA', right: '#E8DAC0' } },
      legend: [
        { label: 'Thèse et conclusion', left: '#EDE8FB', right: '#DCD3F5' },
        { label: 'Objection', left: '#FBE3E3', right: '#F6CACA' },
        { label: 'Réponse', left: '#F6CACA', right: '#E7F3EA' },
        { label: 'Théorie (s’ouvre)', left: '#F1E9DA', right: '#E8DAC0' },
      ],
    },
    rules: {
      chain: 'types', wires: true,
      // Une règle du domaine : une objection ne vise pas directement une thèse ; elle se discute (réponse) ou touche une conclusion.
      list: [{ id: 'objection-visee', on: 'wire', description: 'Une objection se relie à une conclusion, pas à une prémisse.', check: (q) => (q.parent.def.kind === 'objection' || q.parent.def.kind === 'réponse') && q.child.def.kind !== 'conclusion' ? 'Une objection se relie à une conclusion : c’est elle qu’elle affaiblit.' : true }],
    },
    // Les déclarations de ce langage sont des concepts (des variables) : ni classes, ni bibliothèques, ni fonctions.
    modules: { title: 'Concepts', class: false, library: false, function: false, variable: { name: 'Concept', uses: 'Concepts', description: 'Un concept : son nom et sa définition. Il se cite par une pierre « Concept », qui garde le lien même s’il est renommé.' } },
    ui: { pioche: { hide: ['Liens', 'Contexte'] } },
    options: { table: 1300 },
    inspector: { tabs: [tab] },
  });
})(typeof globalThis !== 'undefined' ? globalThis : window);
