/*!
 * Langage · Dominos (le jeu)
 * Le jeu de dominos lui-même, construit avec la plateforme. Une seule pierre, « Pierre a|b » : ses champs disent
 * combien de points montre chaque face, et ses faces (callback `pips`) les montrent. La règle de chaîne du langage
 * est celle du jeu : les faces qui se touchent montrent le même nombre. Pas de fils, pas d'adjacentes.
 * L'onglet « Partie » calcule les coups possibles avec les règles du moteur et joue un coup.
 * (Variante sans blancs : de 1 à 6 points, car une face à zéro ne se colle pas.)
 */
(function (root) {
  'use strict';
  const D = root.Domino;

  const types = [{ name: 'point', label: 'Point', color: '#151718', description: 'Un point de domino, noir sur ivoire.' }];
  // Un point n'est pas une entrée à alimenter : la première pierre posée ne reçoit rien.
  const face = (n) => Array.from({ length: Math.max(1, Math.min(6, Number(n) || 1)) }, () => ({ name: 'point', type: 'point', required: false }));

  const dominos = [{
    type: 'g.tile', name: 'Pierre', category: 'Pierres', represents: 'pièce', kind: 'pièce',
    description: 'Une pierre de domino : a points à gauche, b points à droite. Elle se colle si ses points touchent le même nombre.',
    meaning: { left: 'a : le nombre de points de la face gauche', right: 'b : le nombre de points de la face droite' },
    left: face(1), right: face(1),
    top: false, bottom: false, wires: false,
    fields: { a: { kind: 'number', label: 'Gauche (a)', default: 6, min: 1, max: 6, required: true, bindable: false }, b: { kind: 'number', label: 'Droite (b)', default: 6, min: 1, max: 6, required: true, bindable: false } },
    pips: (api) => ({ left: face(api.raw('a')), right: face(api.raw('b')) }),
    title: (api) => `${api.raw('a')}|${api.raw('b')}${api.raw('a') === api.raw('b') ? ' (double)' : ''}`,
    validate: (api) => {
      const a = api.raw('a'), b = api.raw('b'), key = [a, b].sort().join('|');
      const twin = [...api.workspace.nodes.values()].find((n) => n.id !== api.id && n.type === 'g.tile' && [n.fields.a, n.fields.b].sort().join('|') === key);
      return twin ? [{ level: 'warn', code: 'jeu.double', message: `La pierre ${a}|${b} est déjà sur la table : il n’y en a qu’une par jeu.` }] : [];
    },
    run: (rc) => {
      const s = (rc.inputs[0] && rc.inputs[0].score) || 0, a = Number(rc.fields.a), b = Number(rc.fields.b);
      const total = s + a + b;
      rc.ctx.set('partie.score', total);
      return [{ score: total, bout: b }];
    },
  }];

  const tile = (id, a, b) => ({ id, type: 'g.tile', fields: { a, b } });
  const project = {
    format: 'kantoaplo.domino', version: 2,
    editor: { id: 'jeu', name: 'Dominos' },
    name: 'Une partie',
    context: { main: [[5, 1], [1, 3], [3, 6], [6, 6], [2, 2], [4, 4], [5, 5]], partie: { score: 0 } },
    parties: [{
      id: 'main', kind: 'main', name: 'La table',
      dominos: [{ ...tile('t1', 6, 4), position: { x: 0, y: 40 }, next: [{ pip: 0, domino: { ...tile('t2', 4, 2), next: [{ pip: 0, domino: tile('t3', 2, 5) }] } }] }],
    }],
  };

  // Les coups possibles : on essaie chaque pierre de la main au bout de la chaîne, avec les règles du moteur.
  function moves(ws) {
    const heads = ws.roots('main').filter((n) => n.type === 'g.tile');
    const ends = [];
    for (const h of heads) { let n = h; while (n.next[0] && ws.get(n.next[0].id)) n = ws.get(n.next[0].id); ends.push(n); }
    const hand = ws.context.get('main') || [];
    const out = [];
    hand.forEach(([a, b], k) => {
      for (const [x, y] of a === b ? [[a, b]] : [[a, b], [b, a]]) {
        const temp = new D.Node(ws, { id: '__coup', type: 'g.tile', partie: 'main', fields: { a: x, b: y } });
        for (const end of ends) if (ws.canConnect(end.id, temp).ok) out.push({ k, a: x, b: y, end: end.id });
      }
    });
    return out;
  }
  const tab = {
    id: 'partie', title: 'Partie',
    help: 'Exemple d’onglet propre au langage : la main du joueur, les coups permis par la règle, jouer un coup',
    onEvent: (ev) => ['change', 'run:end', 'load', 'context'].includes(ev.type),
    render: (el, insp) => {
      const ws = insp.ws, ed = insp.ed, e = insp.esc;
      const hand = ws.context.get('main') || [], m = moves(ws);
      const chain = [];
      for (const h of ws.roots('main')) { for (let n = h; n; n = n.next[0] && ws.get(n.next[0].id)) chain.push(`${n.fields.a}|${n.fields.b}`); }
      const mini = (a, b, on) => `<span class="dk-chip${on ? ' on' : ''}" style="font:600 12px var(--f-mono)">${a}|${b}</span>`;
      el.innerHTML = `<div class="dk-split"><div class="dk-pane"><div class="dk-toolbar"><b style="font-size:12px">Sur la table</b><span style="color:var(--ink-3);font-size:11.5px">${chain.length} pierres · score ${ws.context.get('partie.score') ?? '—'} (effet domino pour compter)</span></div>
        <div style="padding:12px 14px;font:600 15px var(--f-mono);letter-spacing:.04em">${chain.map(e).join(' · ') || '—'}</div></div>
        <div class="dk-pane"><div class="dk-toolbar"><b style="font-size:12px">Main du joueur</b><span style="color:var(--ink-3);font-size:11.5px">${D.plural(m.length, 'coup permis', 'coups permis')} par la règle du jeu</span><button class="dk-btn primary" data-play ${m.length ? '' : 'disabled'} style="margin-left:auto">Jouer un coup</button></div>
        <div style="padding:12px 14px;display:flex;gap:6px;flex-wrap:wrap">${hand.map(([a, b], k) => mini(a, b, m.some((x) => x.k === k))).join('') || '<span style="color:var(--ink-3)">main vide : partie gagnée !</span>'}</div>
        <p style="margin:0 14px 12px;color:var(--ink-3);font-size:11.5px">En vert : les pierres qui se collent au bout de la chaîne. Le moteur les trouve avec <code>canConnect</code>, la même règle que le glisser.</p></div></div>`;
      const b = el.querySelector('[data-play]');
      if (b) b.addEventListener('click', () => {
        const c = m[0];
        if (!c) return;
        const before = ed._positions();
        let created;
        ws.transact('Jouer un coup', () => {
          created = ws.create('g.tile', { fields: { a: c.a, b: c.b }, how: 'jeu' });
          ws.connect(c.end, created.id);
          ws.context.set('main', hand.filter((_, k) => k !== c.k));
        });
        ed._renderNow(before);
        ed.select(created.id);
      });
    },
  };

  (D.packs = D.packs || {}).jeu = D.language({
    id: 'jeu', name: 'Dominos', color: '#E2A812',
    description: 'Le jeu de dominos, construit avec la plateforme : une pierre a|b, la règle « même nombre de points », les coups permis calculés par le moteur.',
    types, dominos, project, context: project.context,
    semantics: (l, r, def, base) => ({ label: 'Pierre', text: `${l} point${l > 1 ? 's' : ''} à gauche, ${r} à droite : elle se colle derrière une pierre qui montre ${l} à droite.` }),
    rules: { chain: 'count', wires: false },
    ui: { pioche: { hide: ['Liens', 'Contexte'] } },
    options: { table: 1200, values: false },
    inspector: { tabs: [tab] },
  });
})(typeof globalThis !== 'undefined' ? globalThis : window);
