/*!
 * Démo · l'exemple « Kýdos Belote » : la collection Postman du dépôt (postmanFile/), importée, plus deux
 * scénarios écrits à la main qui montrent chaque idée de l'éditeur :
 *
 *   1. « Parcours joueur » : une variable locale ({{$guid}}), la connexion (le jeton et l'identifiant extraits
 *      vers l'environnement), le profil, puis « Si » : avec un jeton, les préférences ; sinon, un message.
 *   2. « Robots, cycle de vie » : il appelle le parcours joueur (réutilisé), crée un robot, le relit, le modifie
 *      avec une donnée posée au-dessus de la requête, passe son identifiant par un FIL à la création d'une
 *      équipe, le supprime, puis vérifie qu'il n'existe plus (404 attendu).
 *
 * Puis un scénario par dossier de la collection (les 87 requêtes, avec leurs scripts devenus pierres).
 * L'environnement « Local » reçoit aussi la variable que la collection emploie sans la définir ({{cardAssetId}}).
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const P = D.Postman;

  /** Une requête de la collection par méthode et chemin, avec ses pierres (vérifications, extractions). */
  const from = (cat, mk, method, path) => {
    const r = cat.requests.find((x) => x.method === method && x.path === path);
    if (!r) throw new Error(`exemple : la requête ${method} ${path} manque dans la collection`);
    return P.requestSteps(r, mk).request;
  };
  const step = (mk, type, fields, extra = {}) => ({ id: mk(), type, fields, ...extra });
  const below = (req, ...steps) => { req.bottom = [...(req.bottom || []), ...steps.map((d) => ({ pip: 0, domino: d }))]; return req; };

  function parcours(cat, mk) {
    const login = below(from(cat, mk, 'POST', '/auth/login'), step(mk, 'tnr.assert', { name: 'connexion en moins d’une seconde', target: 'temps', op: '<', expected: '1000' }));
    const me = below(from(cat, mk, 'GET', '/auth/me'), step(mk, 'tnr.assert', { name: 'le profil a un identifiant', target: 'champ', path: 'user.id', op: 'existe' }));
    const settings = from(cat, mk, 'PUT', '/settings');
    const si = step(mk, 'tnr.if', { cond: D.Expr.parse('env.token != ""') });
    si.next = [{ pip: 0, domino: settings }, { pip: 1, domino: step(mk, 'tnr.log', { message: 'Pas de jeton : la connexion a échoué, les préférences ne sont pas modifiées.', level: 'erreur' }) }];
    const head = P.chain([
      step(mk, 'tnr.begin', {}, { position: { x: 0, y: 0 } }),
      step(mk, 'tnr.set', { variable: 'runId', value: '{{$guid}}', scope: 'locale' }),
      step(mk, 'tnr.log', { message: 'Parcours {{runId}} : connexion de {{username}}', level: 'info' }),
      login,
      step(mk, 'tnr.log', { message: 'Connecté : utilisateur {{userId}}', level: 'info' }),
      me,
      si,
    ]);
    return { id: mk(), name: 'Parcours joueur', description: 'Connexion, profil, puis préférences seulement si un jeton a été obtenu.', dominos: [head] };
  }

  function robots(cat, mk) {
    const create = from(cat, mk, 'POST', '/robots');
    // L'extraction de l'identifiant n'est pas facultative ici : sans robot, le reste n'a pas de sens.
    const extractId = (create.bottom || []).map((a) => a.domino).find((d) => d.type === 'tnr.extract');
    if (extractId) extractId.fields.optional = false;
    below(create, step(mk, 'tnr.assert', { name: 'robot créé', target: 'statut', op: '=', expected: '201' }));
    const detail = below(from(cat, mk, 'GET', '/robots/{{robotId}}'), step(mk, 'tnr.assert', { name: 'le robot relu est le bon', target: 'champ', path: 'robot.id', op: '=', expected: '{{robotId}}' }));
    const update = below(from(cat, mk, 'PUT', '/robots/{{robotId}}'), step(mk, 'tnr.assert', { name: 'le nouveau nom est gardé', target: 'champ', path: 'robot.name', op: '=', expected: 'Athéna II' }));
    // Une donnée posée au-dessus de la requête : fusionnée dans son corps.
    update.top = [{ pip: 1, domino: step(mk, 'tnr.data', { json: { name: 'Athéna II', responseTimeMs: 650 } }) }];
    // La création d'équipe reçoit l'identifiant du robot par un fil (clé « robotId » de son corps).
    const team = from(cat, mk, 'POST', '/teams');
    team.fields.dataKey = 'robotId';
    team.fields.name = 'Créer une équipe avec ce robot';
    below(team, step(mk, 'tnr.assert', { name: 'l’équipe porte le robot', target: 'champ', path: 'team.robotId', op: '=', expected: '{{robotId}}' }));
    const del = from(cat, mk, 'DELETE', '/robots/{{robotId}}');
    const gone = below(from(cat, mk, 'GET', '/robots/{{robotId}}'), step(mk, 'tnr.assert', { name: 'le robot supprimé n’existe plus', target: 'statut', op: '=', expected: '404' }));
    gone.fields.name = 'Relire le robot supprimé';
    gone.bottom = gone.bottom.filter((a) => !(a.domino.type === 'tnr.assert' && a.domino.fields.op === '2xx'));
    const head = P.chain([
      step(mk, 'tnr.begin', {}, { position: { x: 0, y: 0 } }),
      step(mk, 'tnr.call', { scenario: 'Parcours joueur' }),
      create, detail, update, team,
      step(mk, 'tnr.wait', { ms: 150 }),
      del, gone,
    ]);
    const wires = extractId ? [{ id: mk(), from: { domino: extractId.id, pip: 1 }, to: { domino: team.id, pip: 1 }, label: 'robotId' }] : [];
    return { id: mk(), name: 'Robots, cycle de vie', description: 'Créer, relire, modifier, associer à une équipe, supprimer : chaque étape vérifiée, l’identifiant passé d’une pierre à l’autre.', dominos: [head], wires };
  }

  /** Le projet d'exemple, construit depuis les fichiers Postman embarqués (belote.sample.js). */
  function example(sample) {
    const envs = sample.environments.map((e) => JSON.parse(JSON.stringify(e)));
    // La variable que la collection emploie sans la définir, ajoutée à l'environnement avec une valeur de démonstration.
    // Et un tournoi de démonstration : la collection lit {{tournamentId}} sans jamais en créer (création réservée au back-office).
    if (envs[0] && !envs[0].values.some((v) => v.key === 'cardAssetId')) envs[0].values.push({ key: 'cardAssetId', value: 'dos-de-carte-classique', type: 'default', enabled: true });
    const t = envs[0] && envs[0].values.find((v) => v.key === 'tournamentId');
    if (t && !t.value) t.value = 'tournoi-de-demonstration';
    return P.importCollection(sample.collection, { environments: envs, name: 'Kýdos Belote · non-régression', extraScenarios: [parcours, robots] });
  }

  D.TNR = Object.assign(D.TNR || {}, { example });
})(typeof globalThis !== 'undefined' ? globalThis : window);
