/*!
 * Générateurs génériques : ils servent TOUS les langages (language: '*'), parce qu'ils lisent le document de
 * modèle (input: 'model') et non les types de pierres d'un langage. Ils montrent le point d'extension
 * Domino.Codegen sans toucher à un seul langage :
 *
 *   doc/markdown   la documentation du projet (parties, pierres dans l'ordre de lecture, relations, déclarations, problèmes) ;
 *   graph/mermaid  le graphe du projet (collages, adjacentes, fils), lisible par Mermaid ;
 *   model/json     le document de modèle lui-même, deux fichiers : le modèle et son schéma.
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  if (!D || !D.Codegen) return;

  const val = (f) => {
    const v = f.resolved !== undefined ? f.resolved : f.value !== undefined ? f.value : f.default;
    if (f.ref) return `↪ ${f.ref.title || f.ref.id}`;
    if (v === undefined) return '—';
    const s = typeof v === 'string' ? v : JSON.stringify(v);
    return s.length > 60 ? `${s.slice(0, 59)}…` : s;
  };
  const md = (s) => String(s == null ? '' : s).replace(/\|/g, '\\|').replace(/\n/g, ' ');

  D.Codegen.register({
    id: 'doc/markdown', language: '*', target: 'markdown', label: 'Documentation', extension: 'md', input: 'model',
    description: 'La documentation du projet, depuis le document de modèle.',
    options: { fields: { kind: 'toggle', label: 'Champs des pierres', default: true } },
    generate(ctx) {
      const m = ctx.model(), E = m.elements;
      const out = [`# ${m.project.name}`, '', `Langage : **${m.language.name}** · ${m.project.stats.elements} pierres · ${m.project.stats.connections} relations · ${m.project.stats.wires} fils.`, ''];
      for (const p of m.parties) {
        if (!(p.elements || []).length) continue;
        out.push(`## ${p.path.join(' › ')}`, '', `| # | Pierre | Ce qu’elle est | Points | ${ctx.options.fields ? 'Champs |' : ''}`, `|---|---|---|---|${ctx.options.fields ? '---|' : ''}`);
        p.elements.forEach((id, i) => {
          const e = E[id];
          const fields = Object.entries(e.fields).map(([k, f]) => `${f.label || k} = ${val(f)}`).join(' ; ');
          const what = [e.represents, e.roleLabel].filter(Boolean).join(', ');
          out.push(`| ${i + 1} | ${'↳ '.repeat(Math.min(3, e.place.depth || 0))}${md(e.title)} | ${md(what)} | ${md(e.faces.count)} | ${ctx.options.fields ? `${md(fields)} |` : ''}`);
        });
        out.push('');
      }
      if (m.declarations.length) {
        out.push('## Déclarations', '');
        for (const d of m.declarations) out.push(`- **${d.name}** (${d.kind})${d.instances && d.instances.length ? ` · ${d.instances.length} instance(s)` : ''}${d.uses && d.uses.length ? ` · ${d.uses.length} usage(s)` : ''}`);
        out.push('');
      }
      const wires = m.connections.filter((c) => c.kind === 'wire');
      if (wires.length) {
        out.push('## Fils', '');
        for (const w of wires) out.push(`- ${md(E[w.from.element] ? E[w.from.element].title : w.from.element)} → ${md(E[w.to.element] ? E[w.to.element].title : w.to.element)}${w.blocking === false ? ' (non bloquant)' : ''}${w.label ? ` · « ${md(w.label)} »` : ''}`);
        out.push('');
      }
      out.push('## Problèmes', '');
      if (!m.diagnostics.length) out.push('Aucun.');
      for (const d of m.diagnostics) out.push(`- ${d.level === 'error' ? '⛔' : '⚠'} ${md(E[d.element] ? E[d.element].title : d.element)} : ${md(d.message)}`);
      out.push('');
      return out.join('\n');
    },
  });

  D.Codegen.register({
    id: 'graph/mermaid', language: '*', target: 'mermaid', label: 'Graphe Mermaid', extension: 'mmd', input: 'model',
    description: 'Le graphe du projet : chaque pierre, chaque collage, chaque adjacente, chaque fil.',
    generate(ctx) {
      const m = ctx.model(), E = m.elements;
      const id = (x) => `n_${String(x).replace(/[^\w]/g, '_')}`;
      const label = (x) => `"${String(E[x] ? E[x].title : x).replace(/"/g, '\'')}"`;
      const out = ['flowchart LR'];
      for (const p of m.parties) {
        if (!(p.elements || []).length) continue;
        out.push(`  subgraph ${id(`p_${p.id}`)}["${p.path.join(' › ').replace(/"/g, '\'')}"]`);
        for (const e of p.elements) out.push(`    ${id(e)}[${label(e)}]`);
        out.push('  end');
      }
      for (const c of m.connections) {
        if (c.kind === 'chain') out.push(`  ${id(c.from.element)} --> ${id(c.to.element)}`);
        else if (c.kind === 'top') out.push(`  ${id(c.from.element)} -.-> ${id(c.to.element)}`);
        else if (c.kind === 'bottom') out.push(`  ${id(c.from.element)} -.-> ${id(c.to.element)}`);
        else if (c.kind === 'wire') out.push(`  ${id(c.from.element)} ==>${c.label ? `|${String(c.label).replace(/\|/g, '/')}|` : ''} ${id(c.to.element)}`);
      }
      return out.join('\n');
    },
  });

  D.Codegen.register({
    id: 'model/json', language: '*', target: 'json', label: 'Document de modèle', extension: 'json', input: 'model',
    description: 'Le document de modèle et son schéma (deux fichiers).',
    generate(ctx) {
      const base = D.Resource ? D.Resource.slug(ctx.json.name || 'projet') : 'projet';
      ctx.file(`${base}.model.json`, JSON.stringify(ctx.model(), null, 2), 'application/json');
      ctx.file('model.schema.json', JSON.stringify(D.describe.schema, null, 2), 'application/json');
      return { files: [] };
    },
  });
})(typeof globalThis !== 'undefined' ? globalThis : window);
