/*!
 * Démo · Concepteur d'API
 * Trois routes, trois middlewares (CORS, Auth JWT, limite de débit) et des composants de bibliothèque.
 * Tout ce qui est propre au domaine est ici : le moteur Domino ne sait pas ce qu'est une API.
 */
(function (root) {
  'use strict';
  const D = root.Domino;

  const types = [
    { name: 'request', label: 'Requête', color: '#3B7DDD', description: 'La requête HTTP, enrichie par chaque middleware.' },
    { name: 'data', label: 'Données', color: '#6A5BDC', description: 'Un corps, des lignes, un objet métier.' },
    { name: 'schema', label: 'Schéma', color: '#E2A812', description: 'La forme attendue d’un corps de requête.' },
    { name: 'secret', label: 'Secret', color: '#D9539A', description: 'Une clé, toujours lue dans le contexte, jamais écrite en dur.' },
    { name: 'error', label: 'Erreur', color: '#E5484D', description: 'Une erreur HTTP à rendre au client.' },
  ];

  const dominos = [
    {
      type: 'api.route', name: 'Route', category: 'Routes',
      description: 'Point d’entrée HTTP. Face gauche à zéro : une route commence toujours une chaîne.',
      right: [{ name: 'requête', type: 'request' }],
      fields: { method: { kind: 'select', label: 'Méthode', options: ['GET', 'POST', 'PUT', 'DELETE'], default: 'GET', bindable: false }, path: { kind: 'text', label: 'Chemin', default: '/ressource' } },
      title: (api) => `${api.field('method')} ${api.field('path')}`,
      validate: (api) => (String(api.field('path')).startsWith('/') ? [] : [{ level: 'error', code: 'api.path', message: 'Un chemin commence par « / ».' }]),
      run: (rc) => [{ method: rc.fields.method, path: rc.fields.path, headers: rc.ctx.get('request.headers') || {}, body: rc.ctx.get('request.body') ?? null }],
    },
    {
      type: 'mw.cors', name: 'CORS', category: 'Middlewares',
      description: 'Autorise les appels depuis d’autres origines.',
      left: [{ name: 'requête', type: 'request' }], right: [{ name: 'requête', type: 'request' }],
      fields: { origin: { kind: 'text', label: 'Origine', default: '*' } },
      validate: (api) => (api.field('origin') === '*' && api.context.get('env.STAGE') === 'production' ? [{ level: 'warn', code: 'api.cors', message: 'CORS ouvert à toutes les origines en production.' }] : []),
      run: (rc) => [{ ...rc.inputs[0], cors: rc.fields.origin }],
    },
    {
      type: 'mw.auth', name: 'Auth JWT', category: 'Middlewares',
      description: 'Vérifie le jeton. Le secret arrive par une adjacente haute, liée au contexte.',
      left: [{ name: 'requête', type: 'request' }, { name: 'secret', type: 'secret' }], right: [{ name: 'requête', type: 'request' }],
      fields: { scheme: { kind: 'select', label: 'Schéma', options: ['Bearer', 'Basic'], default: 'Bearer', bindable: false } },
      run: (rc) => {
        const [req, secret] = rc.inputs;
        if (!secret) throw new Error('secret absent : collez « Lire le contexte » (env.JWT_SECRET) en adjacente haute.');
        const h = (req.headers && req.headers.authorization) || '';
        if (!h.startsWith(rc.fields.scheme)) throw new Error('401 : en-tête Authorization absent ou invalide.');
        rc.log('info', `jeton accepté pour ${req.method} ${req.path}`);
        return [{ ...req, user: { id: 'u_42', scopes: ['lire', 'écrire'] } }];
      },
    },
    {
      type: 'mw.rate', name: 'Limite de débit', category: 'Middlewares',
      description: 'Refuse au-delà de N appels par minute (429).',
      left: [{ name: 'requête', type: 'request' }], right: [{ name: 'requête', type: 'request' }],
      fields: { perMinute: { kind: 'number', label: 'Par minute', default: 60 } },
      title: (api) => `Limite ${api.field('perMinute')}/min`,
      run: (rc) => {
        const n = (rc.ctx.get('stats.calls') || 0) + 1;
        rc.ctx.set('stats.calls', n);
        if (n > rc.fields.perMinute) throw new Error(`429 : ${n} appels, limite ${rc.fields.perMinute}/min.`);
        return [rc.inputs[0]];
      },
    },
    {
      type: 'lib.validate', name: 'Valider le corps', category: 'Bibliothèque',
      description: 'Deux sorties : le corps valide, ou une erreur 400. Le schéma arrive en adjacente haute.',
      left: [{ name: 'requête', type: 'request' }, { name: 'schéma', type: 'schema' }],
      right: [{ name: 'valide', type: 'data' }, { name: 'invalide', type: 'error' }],
      run: (rc) => {
        const [req, schema] = rc.inputs;
        const body = (req && req.body) || {};
        const missing = ((schema && schema.required) || []).filter((k) => body[k] == null);
        return missing.length ? [undefined, { status: 400, message: `champs manquants : ${missing.join(', ')}` }] : [body, undefined];
      },
    },
    {
      type: 'lib.query', name: 'Lire en base', category: 'Bibliothèque',
      description: 'Lit une table. La table arrive en adjacente haute.',
      left: [{ name: 'requête', type: 'request' }, { name: 'table', type: 'data' }], right: [{ name: 'lignes', type: 'data' }],
      run: (rc) => { const t = rc.inputs[1] || {}; return [rc.ctx.get(`db.${t.name}`) || []]; },
    },
    {
      type: 'lib.paginate', name: 'Paginer', category: 'Bibliothèque',
      left: [{ name: 'lignes', type: 'data' }], right: [{ name: 'page', type: 'data' }],
      fields: { size: { kind: 'number', label: 'Taille', default: 20 } },
      run: (rc) => { const rows = rc.inputs[0] || []; return [{ items: rows.slice(0, rc.fields.size), total: rows.length }]; },
    },
    {
      type: 'lib.create', name: 'Créer en base', category: 'Bibliothèque',
      left: [{ name: 'données', type: 'data' }], right: [{ name: 'ligne', type: 'data' }],
      fields: { table: { kind: 'text', label: 'Table', default: 'orders' } },
      title: (api) => `Créer dans ${api.field('table')}`,
      run: (rc) => {
        const list = rc.ctx.get(`db.${rc.fields.table}`) || [];
        const row = { id: `o_${list.length + 1}`, ...rc.inputs[0] };
        rc.ctx.set(`db.${rc.fields.table}`, [...list, row]);
        return [row];
      },
    },
    {
      type: 'lib.ping', name: 'Ping', category: 'Bibliothèque',
      left: [{ name: 'requête', type: 'request' }], right: [{ name: 'état', type: 'data' }],
      run: () => [{ status: 'ok', version: '1.4.0' }],
    },
    {
      type: 'res.json', name: 'Répondre', category: 'Réponses',
      description: 'Face droite à zéro : la réponse termine la chaîne.',
      left: [{ name: 'corps', type: 'data' }],
      fields: { status: { kind: 'select', label: 'Statut', options: [200, 201, 204], default: 200, bindable: false } },
      title: (api) => `Répondre ${api.field('status')}`,
      run: (rc) => { rc.ctx.set('response', { status: Number(rc.fields.status), body: rc.inputs[0] }); return []; },
    },
    {
      type: 'res.error', name: 'Erreur HTTP', category: 'Réponses',
      left: [{ name: 'erreur', type: 'error' }],
      fields: { status: { kind: 'select', label: 'Statut', options: [400, 401, 404, 422], default: 400, bindable: false } },
      title: (api) => `Erreur ${api.field('status')}`,
      run: (rc) => { rc.ctx.set('response', { status: Number(rc.fields.status), body: rc.inputs[0] }); return []; },
    },
    {
      type: 'src.schema', name: 'Schéma', category: 'Sources',
      description: 'Source (0 | 1) : se colle en adjacente haute de « Valider le corps ».',
      right: [{ name: 'schéma', type: 'schema' }],
      fields: { name: { kind: 'text', label: 'Nom', default: 'Commande' }, required: { kind: 'json', label: 'Champs requis', default: ['client', 'articles'] } },
      title: (api) => `Schéma ${api.field('name')}`,
      run: (rc) => [{ name: rc.fields.name, required: rc.fields.required }],
    },
    {
      type: 'src.table', name: 'Table', category: 'Sources',
      right: [{ name: 'table', type: 'data' }],
      fields: { name: { kind: 'text', label: 'Nom', default: 'users' } },
      title: (api) => `Table ${api.field('name')}`,
      run: (rc) => [{ name: rc.fields.name }],
    },
    {
      type: 'obs.log', name: 'Journal d’accès', category: 'Observabilité',
      description: 'Terminale (1 | 0) : se colle en adjacente basse et reçoit une sortie.',
      left: [{ name: 'entrée', type: 'any' }],
      run: (rc) => { const v = rc.inputs[0]; rc.log('log', `accès ${v && v.method ? `${v.method} ${v.path} par ${v.user ? v.user.id : 'anonyme'}` : JSON.stringify(v).slice(0, 80)}`); return []; },
    },
    {
      type: 'obs.metrics', name: 'Métriques', category: 'Observabilité',
      left: [{ name: 'valeur', type: 'any' }],
      fields: { name: { kind: 'text', label: 'Compteur', default: 'http_requests_total' } },
      run: (rc) => { const k = `metrics.${rc.fields.name}`; rc.ctx.set(k, (rc.ctx.get(k) || 0) + 1); return []; },
    },
  ];

  const secret = (id) => ({ pip: 1, domino: { id, type: 'ctx.get', fields: { path: 'env.JWT_SECRET' } } });
  const project = {
    format: 'kantoaplo.domino', version: 1,
    editor: { id: 'api', name: 'Concepteur d’API' },
    name: 'API Boutique',
    context: {
      env: { JWT_SECRET: 's3cr3t-demo', STAGE: 'recette', BASE_URL: 'https://api.boutique.test' },
      request: { headers: { authorization: 'Bearer eyJhbGciOiJIUzI1NiJ9.demo' }, body: { client: 'c_7', articles: [{ sku: 'D-66', qty: 2 }] } },
      db: { users: [{ id: 'u1', name: 'Ada' }, { id: 'u2', name: 'Grace' }, { id: 'u3', name: 'Linus' }], orders: [] },
      stats: { calls: 0 },
    },
    parties: [{
      id: 'main', name: 'Routes',
      dominos: [
        {
          id: 'r1', type: 'api.route', fields: { method: 'GET', path: '/users' },
          next: [{ pip: 0, domino: {
            id: 'c1', type: 'mw.cors', fields: { origin: '*' },
            next: [{ pip: 0, domino: {
              id: 'a1', type: 'mw.auth', fields: { scheme: 'Bearer' }, top: [secret('s1')],
              bottom: [{ pip: 0, domino: { id: 'l1', type: 'obs.log' } }],
              next: [{ pip: 0, domino: {
                id: 'q0', type: 'mw.rate', fields: { perMinute: 60 },
                next: [{ pip: 0, domino: {
                  id: 'q1', type: 'lib.query', top: [{ pip: 1, domino: { id: 't1', type: 'src.table', fields: { name: 'users' } } }],
                  next: [{ pip: 0, domino: {
                    id: 'pg', type: 'lib.paginate', fields: { size: 20 }, bottom: [{ pip: 0, domino: { id: 'm1', type: 'obs.metrics' } }],
                    next: [{ pip: 0, domino: { id: 'rs1', type: 'res.json', fields: { status: 200 } } }],
                  } }],
                } }],
              } }],
            } }],
          } }],
        },
        {
          id: 'r2', type: 'api.route', fields: { method: 'POST', path: '/orders' },
          next: [{ pip: 0, domino: {
            id: 'c2', type: 'mw.cors', fields: { origin: 'https://boutique.test' },
            next: [{ pip: 0, domino: {
              id: 'a2', type: 'mw.auth', fields: { scheme: 'Bearer' }, top: [secret('s2')],
              next: [{ pip: 0, domino: {
                id: 'v2', type: 'lib.validate', top: [{ pip: 1, domino: { id: 'sc', type: 'src.schema', fields: { name: 'Commande', required: ['client', 'articles'] } } }],
                next: [
                  { pip: 0, label: 'valide', domino: {
                    id: 'cr', type: 'lib.create', fields: { table: 'orders' }, bottom: [{ pip: 0, domino: { id: 'm2', type: 'obs.metrics', fields: { name: 'orders_created_total' } } }],
                    next: [{ pip: 0, domino: { id: 'rs2', type: 'res.json', fields: { status: 201 } } }],
                  } },
                  { pip: 1, label: 'invalide', domino: { id: 'er', type: 'res.error', fields: { status: 400 } } },
                ],
              } }],
            } }],
          } }],
        },
        {
          id: 'r3', type: 'api.route', fields: { method: 'GET', path: '/health' },
          next: [{ pip: 0, domino: { id: 'p3', type: 'lib.ping', next: [{ pip: 0, domino: { id: 'rs3', type: 'res.json', fields: { status: 200 } } }] } }],
        },
      ],
    }],
  };

  // ---------------------------------------------------------------------------
  // Générateurs : ils ne lisent que le JSON du projet.
  // ---------------------------------------------------------------------------
  const chainOf = (head, g) => { const out = []; for (let n = head; n; n = g.next(n, 0)) out.push(n); return out; };
  const routes = (json) => json.parties.flatMap((p) => p.dominos.filter((d) => d.type === 'api.route'));

  const openapi = new D.Generator('openapi', { label: 'OpenAPI 3.1', extension: 'yaml' }).on('project', (json, g) => {
    const lines = ['openapi: 3.1.0', 'info:', `  title: ${json.name || 'API'}`, '  version: 1.0.0', `servers:\n  - url: ${(json.context && json.context.env && json.context.env.BASE_URL) || 'https://api.test'}`, 'paths:'];
    const byPath = {};
    for (const r of routes(json)) (byPath[r.fields.path] ||= []).push(r);
    for (const [path, list] of Object.entries(byPath)) {
      lines.push(`  ${path}:`);
      for (const r of list) {
        const all = []; const walk = (n) => { if (!n) return; all.push(n); (n.next || []).forEach((l) => walk(l.domino)); };
        walk(r);
        const auth = all.some((n) => n.type === 'mw.auth');
        const val = all.find((n) => n.type === 'lib.validate');
        const schema = val && g.top(val, 1)[0];
        lines.push(`    ${r.fields.method.toLowerCase()}:`, `      operationId: ${r.fields.method.toLowerCase()}${path.replace(/\W+(\w)?/g, (_, c) => (c || '').toUpperCase())}`);
        if (auth) lines.push('      security:', '        - bearerAuth: []');
        if (schema) lines.push('      requestBody:', '        required: true', '        content:', '          application/json:', `            schema: { $ref: '#/components/schemas/${schema.fields.name}' }`);
        lines.push('      responses:');
        for (const n of all.filter((x) => x.type === 'res.json' || x.type === 'res.error')) lines.push(`        '${n.fields.status}':`, `          description: ${n.type === 'res.error' ? 'Erreur' : 'Succès'}`);
        if (auth) lines.push("        '401':", '          description: Jeton absent ou invalide');
        if (all.some((n) => n.type === 'mw.rate')) lines.push("        '429':", '          description: Trop de requêtes');
      }
    }
    const schemas = g.all().filter((n) => n.type === 'src.schema');
    lines.push('components:', '  securitySchemes:', '    bearerAuth: { type: http, scheme: bearer }');
    if (schemas.length) {
      lines.push('  schemas:');
      for (const s of schemas) lines.push(`    ${s.fields.name}:`, '      type: object', `      required: [${(s.fields.required || []).join(', ')}]`);
    }
    return lines.join('\n');
  });

  const express = new D.Generator('express', { label: 'Express (Node.js)', extension: 'js' });
  express.forTypes({
    'mw.cors': (n) => `cors({ origin: '${n.fields.origin}' })`,
    'mw.auth': (n, g) => { const s = g.top(n, 1)[0]; return `jwt({ secret: ${s && s.type === 'ctx.get' ? `process.env.${s.fields.path.split('.').pop()}` : "'?'"} })`; },
    'mw.rate': (n) => `rateLimit({ windowMs: 60_000, max: ${n.fields.perMinute} })`,
    'lib.query': (n, g) => { const t = g.top(n, 1)[0]; return `let data = await db.${t ? t.fields.name : 'table'}.find();`; },
    'lib.paginate': (n) => `data = { items: data.slice(0, ${n.fields.size}), total: data.length };`,
    'lib.create': (n) => `data = await db.${n.fields.table}.insert(data);`,
    'lib.ping': () => "let data = { status: 'ok' };",
    'lib.validate': (n, g) => { const s = g.top(n, 1)[0]; const bad = g.next(n, 1); return `const missing = [${((s && s.fields.required) || []).map((k) => `'${k}'`).join(', ')}].filter((k) => req.body[k] == null);\nif (missing.length) return ${bad ? g.node(bad).replace(/;$/, '') : 'res.status(400).end()'};\nlet data = req.body;`; },
    'res.json': (n) => `res.status(${n.fields.status}).json(data);`,
    'res.error': (n) => `res.status(${n.fields.status}).json({ error: 'champs manquants', missing })`,
    'obs.log': () => 'log.info(req.method, req.path, req.user?.id);',
    'obs.metrics': (n) => `metrics.inc('${n.fields.name}');`,
  }).on('project', (json, g) => {
    const out = ["import express from 'express';", "import cors from 'cors';", "import jwt from 'express-jwt';", "import rateLimit from 'express-rate-limit';", "import { db, log, metrics } from './services.js';", '', 'const app = express();', 'app.use(express.json());', ''];
    for (const r of routes(json)) {
      const chain = chainOf(g.next(r, 0), g);
      const mws = chain.filter((n) => n.type.startsWith('mw.'));
      const body = [];
      for (const n of chain.filter((x) => !x.type.startsWith('mw.'))) {
        body.push(g.node(n));
        g.bottom(n).forEach((b) => body.push(g.node(b)));
      }
      mws.forEach((m) => g.bottom(m).forEach((b) => body.unshift(g.node(b))));
      out.push(`// ${r.fields.method} ${r.fields.path}`, `app.${r.fields.method.toLowerCase()}('${r.fields.path}',${mws.map((m) => `\n  ${g.node(m)},`).join('')}\n  async (req, res) => {`, g.indent(body.join('\n'), 2), '  });', '');
    }
    out.push('app.listen(3000);');
    return out.join('\n');
  });

  // ---------------------------------------------------------------------------
  // Onglet d'entreprise : la politique de sécurité de la maison, vérifiée sur le JSON.
  // ---------------------------------------------------------------------------
  const POLICY = { public: ['/health'], writeNeedsRate: false };
  const audit = (editor) => {
    const json = editor.toJSON();
    const g = new D.Generator('audit');
    g.generate(json);
    return routes(json).map((r) => {
      const all = []; const walk = (n) => { if (!n) return; all.push(n); (n.next || []).forEach((l) => walk(l.domino)); };
      walk(r);
      const auth = all.find((n) => n.type === 'mw.auth');
      const rate = all.find((n) => n.type === 'mw.rate');
      const cors = all.find((n) => n.type === 'mw.cors');
      const issues = [];
      const pub = POLICY.public.includes(r.fields.path);
      if (!auth && !pub) issues.push('aucune authentification');
      if (auth && !g.top(auth, 1).length) issues.push('secret non lié');
      if (!rate && r.fields.method === 'GET' && !pub) issues.push('pas de limite de débit');
      if (cors && cors.fields.origin === '*') issues.push('CORS ouvert à tous');
      return { r, auth, rate, cors, pub, issues };
    });
  };

  D.packs.api = {
    id: 'api', name: 'Concepteur d’API', color: '#3B7DDD',
    description: 'Routes, middlewares et composants de bibliothèque. Génère OpenAPI et Express.',
    types, dominos, project,
    context: project.context,
    generators: [openapi, express],
    options: { table: 1250 },
    inspector: {
      tabs: [{
        id: 'security', title: 'Sécurité (entreprise)', help: 'Exemple d’onglet propre à une entreprise : sa politique de sécurité',
        badge: (insp) => { const n = audit(insp.ed).filter((a) => a.issues.length).length; return n ? { n, kind: 'warn' } : null; },
        onEvent: (ev) => ['change', 'load'].includes(ev.type),
        render: (el, insp) => {
          const rows = audit(insp.ed);
          el.innerHTML = `<div class="dk-pane"><div class="dk-toolbar"><b style="font-size:12px">Politique « Boutique » v3</b><span style="color:var(--ink-3);font-size:11.5px">Toute route est authentifiée sauf ${POLICY.public.map((p) => `<code>${p}</code>`).join(', ')} ; les lectures sont limitées ; CORS jamais ouvert à tous. Cet onglet n’existe que pour cette entreprise : il est déclaré par son pack.</span></div>
            <table class="dk-table"><thead><tr><th>route</th><th>auth</th><th>limite</th><th>CORS</th><th>verdict</th></tr></thead><tbody>${rows.map((a) => `<tr><td>${insp.link(a.r.id, `${a.r.fields.method} ${a.r.fields.path}`)}${a.pub ? ' <span style="color:var(--ink-3)">(publique)</span>' : ''}</td><td>${a.auth ? insp.link(a.auth.id, '✓ JWT') : '—'}</td><td>${a.rate ? insp.link(a.rate.id, `✓ ${a.rate.fields.perMinute}/min`) : '—'}</td><td>${a.cors ? insp.esc(a.cors.fields.origin) : '—'}</td><td>${a.issues.length ? `<span style="color:var(--warn)">${insp.esc(a.issues.join(' · '))}</span>` : '<span style="color:var(--ok)">conforme</span>'}</td></tr>`).join('')}</tbody></table></div>`;
          insp.wire(el);
        },
      }],
    },
  };
})(typeof globalThis !== 'undefined' ? globalThis : window);
