/*!
 * Démo · Scénarios d'API (TNR) : gabarits
 *
 * Le balisage du rapport pour testeur (une requête et sa réponse, une vérification, une variable, un scénario)
 * et du tableau de bord, dans le registre central Domino.Templates : Domino.Templates.override('report.tnr.http',
 * …) change l'affichage sans toucher au langage. L'onglet Rapport trouve « report.<genre> » de lui-même.
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const T = D.Templates;
  if (!T) return;
  const P = () => D.Postman;
  const pretty = (text) => {
    if (text == null || text === '') return '';
    try { const v = typeof text === 'string' ? JSON.parse(text) : text; return D.jsonHTML ? D.jsonHTML(v) : T.esc(JSON.stringify(v, null, 2)); } catch (_) { return T.esc(String(text)); }
  };
  const codeClass = (s) => (!s ? 'err' : s < 300 ? 'ok' : s < 400 ? 'redir' : s < 500 ? 'warn' : 'err');

  // ===========================================================================
  // Rapport (onglet Rapport de l'inspecteur)
  // ===========================================================================
  T.define('tnr.headers', (d, h) => {
    const rows = Object.entries(d.headers || {});
    return rows.length ? h.html`<table class="tnr-kv">${rows.map(([k, v]) => h.html`<tr><th>${k}</th><td>${v}</td></tr>`)}</table>` : h.html`<p class="tnr-none">Aucun en-tête.</p>`;
  }, { description: 'Un tableau d’en-têtes HTTP.', data: '{ headers: { clé: valeur } }' });

  T.define('report.tnr.http', (e, h) => {
    const x = e.details || {}, rq = x.request || {}, rs = x.response || {};
    const m = rq.method || 'GET';
    return h.html`<div class="tnr-http">
      <div class="tnr-line"><span class="tnr-m" style="--m:${P().METHOD_COLOR[m] || 'var(--ink-3)'}">${m}</span><code class="tnr-url">${rq.url}</code>
        ${rs.error ? h.html`<span class="tnr-code err">${rs.error}</span>` : h.html`<span class="tnr-code ${codeClass(rs.status)}">${rs.status} ${rs.statusText || ''}</span>`}
        <span class="tnr-meta">${x.ms != null ? `${x.ms} ms` : ''}${rs.size != null ? ` · ${rs.size} o` : ''} · ${x.transport || ''}</span></div>
      ${x.unknownVariables ? h.html`<p class="tnr-warn">Variables inconnues : ${x.unknownVariables.map((v) => `{{${v}}}`).join(', ')}. Définissez-les dans l’environnement, ou par une pierre « Définir » ou « Extraire » avant cette requête.</p>` : ''}
      ${x.emptyVariables ? h.html`<p class="tnr-warn">Variables vides au moment de l’envoi : ${x.emptyVariables.map((v) => `{{${v}}}`).join(', ')}. Une requête précédente devait sans doute les remplir.</p>` : ''}
      <div class="tnr-cols">
        <section><h5>Requête</h5>${h.render('tnr.headers', { headers: rq.headers })}${rq.body ? h.html`<pre class="dk-json">${h.raw(pretty(rq.body))}</pre>` : ''}</section>
        <section><h5>Réponse</h5>${rs.error ? h.html`<p class="tnr-warn">${rs.error}</p>` : h.html`${h.render('tnr.headers', { headers: rs.headers })}<pre class="dk-json">${h.raw(pretty(rs.body))}</pre>`}</section>
      </div>
      <details class="tnr-curl"><summary>cURL (pour la rejouer dans un terminal)</summary><pre>${x.curl || ''}</pre></details>
    </div>`;
  }, { description: 'Le détail d’une requête exécutée : méthode, adresse, statut, durée, en-têtes et corps de la requête et de la réponse, variables manquantes, cURL.', data: 'entrée de rapport { details: { request, response, ms, transport, unknownVariables?, emptyVariables?, curl } }' });

  T.define('report.tnr.assert', (e, h) => {
    const x = e.details || {};
    return h.html`<table class="tnr-kv"><tr><th>Test</th><td>${x.name || e.summary}</td></tr>${x.target ? h.html`<tr><th>Vérifie</th><td>${x.target}${x.path ? ` · ${x.path}` : ''} ${x.op || ''}</td></tr>` : ''}${'expected' in x ? h.html`<tr><th>Attendu</th><td><code>${JSON.stringify(x.expected)}</code></td></tr>` : ''}${'actual' in x ? h.html`<tr><th>Obtenu</th><td><code>${JSON.stringify(x.actual)}</code></td></tr>` : ''}${x.request ? h.html`<tr><th>Requête</th><td><code>${x.request}</code></td></tr>` : ''}${x.error ? h.html`<tr><th>Erreur</th><td>${x.error}</td></tr>` : ''}</table>`;
  }, { description: 'Le détail d’une vérification : attendu, obtenu, requête.', data: 'entrée de rapport { details: { name, target, path, op, expected, actual, request } }' });

  T.define('report.tnr.var', (e, h) => {
    const x = e.details || {};
    return x.variable ? h.html`<table class="tnr-kv"><tr><th>Variable</th><td><code>{{${x.variable}}}</code> · ${x.scope}</td></tr>${x.from ? h.html`<tr><th>Lue dans</th><td><code>${x.from}</code></td></tr>` : ''}<tr><th>Avant</th><td><code>${JSON.stringify(x.before) ?? '—'}</code></td></tr><tr><th>Après</th><td><code>${JSON.stringify(x.after)}</code></td></tr></table>` : h.html`<p>${e.summary}</p>`;
  }, { description: 'Le détail d’une variable définie ou extraite : portée, source, avant, après (secrets masqués).', data: 'entrée de rapport { details: { variable, scope, from, before, after } }' });

  T.define('report.tnr.scenario', (e, h) => {
    const x = e.details || {};
    return h.html`<div class="tnr-kpis small">${[['Requêtes', x.requests], ['Réussies', x.pass], ['Échecs', x.fail], ['Erreurs', x.errors], ['Temps réseau', `${x.ms || 0} ms`]].map(([k, v]) => h.html`<div class="tnr-kpi"><b>${v ?? 0}</b><small>${k}</small></div>`)}</div>`;
  }, { description: 'Le bilan d’un scénario : requêtes, vérifications réussies et échouées, erreurs, temps.', data: 'entrée de rapport { details: { requests, pass, fail, errors, ms } }' });

  // ===========================================================================
  // Tableau de bord (projection « tnr.dashboard »)
  // ===========================================================================
  T.define('tnr.dash.kpi', (d, h) => h.html`<div class="tnr-kpi ${d.tone || ''}" title="${d.help || ''}"><b>${d.value}</b><small>${d.label}</small>${d.sub ? h.html`<em>${d.sub}</em>` : ''}</div>`,
    { description: 'Un chiffre clé du tableau de bord.', data: '{ label, value, sub?, tone? (ok|fail|warn), help? }' });

  T.define('tnr.dash.request', (d, h) => h.html`<li class="tnr-req${d.covered ? ' covered' : ''}" data-ref="${d.id}" title="${d.description || `${d.method} ${d.url}`}">
      <span class="tnr-m" style="--m:${d.color}">${d.method}</span><span class="nm">${d.name}</span><code class="pth">${d.path}</code>
      <span class="cov" title="${d.covered ? `Couverte par ${d.covered} pierre(s)` : 'Pas encore dans un scénario'}">${d.covered ? `✓ ${d.covered}` : '—'}</span>
      ${d.last ? h.html`<span class="tnr-code ${d.last.cls}" title="Dernière exécution">${d.last.text}</span>` : h.html`<span class="tnr-code idle">·</span>`}
    </li>`,
  { description: 'Une requête de la collection : méthode, nom, chemin, couverture par les scénarios, dernier statut.', data: '{ id, method, color, name, path, url, description?, covered, last?: { text, cls } }' });

  T.define('tnr.dash.folder', (d, h) => h.html`<details class="tnr-folder" ${d.open ? 'open' : ''}><summary><span class="ic">▤</span><b>${d.name}</b><small>${d.count} · ${d.coverage} %</small><span class="bar"><i style="width:${d.coverage}%"></i></span></summary>
      ${d.description ? h.html`<p class="desc">${d.description}</p>` : ''}<ul>${h.raw(d.body)}</ul></details>`,
  { description: 'Un dossier (ou sous-dossier) de la collection, dépliable, avec sa couverture.', data: '{ name, description?, count, coverage (%), open, body (HTML) }' });

  T.define('tnr.dash.scenario', (d, h) => h.html`<li class="tnr-scen ${d.status}" data-open="${d.id}">${h.render('report.status', { status: d.status })}<span class="nm">${d.name}</span><small>${d.meta}</small><span class="ms">${d.ms != null ? `${d.ms} ms` : ''}</span></li>`,
    { description: 'Un scénario de la campagne : statut de la dernière exécution, étapes, durée.', data: '{ id, name, status, meta, ms? }' });

  T.define('tnr.dash.var', (d, h) => h.html`<tr class="${d.changed ? 'changed' : ''}"><th><code>{{${d.key}}}</code>${d.secret ? h.html` <span class="tnr-secret" title="secret">🔒</span>` : ''}</th><td><code>${d.initial}</code></td><td><code>${d.current}</code>${d.changed ? h.html` <em>modifiée</em>` : ''}</td></tr>`,
    { description: 'Une variable de l’environnement : valeur initiale, valeur courante (après exécution), secrète ou non.', data: '{ key, initial, current, changed, secret }' });

  T.define('tnr.dashboard', (d, h) => h.html`<div class="tnr-dash">
    <header class="tnr-top">
      <div class="tnr-title"><h2>${d.name}</h2><p>${d.subtitle}</p></div>
      <div class="tnr-actions">
        <label>Environnement <select data-env>${d.environments.map((e) => h.html`<option ${e === d.environment ? 'selected' : ''}>${e}</option>`)}</select></label>
        <span class="dk-seg" role="group" aria-label="Transport">${['simulé', 'réseau'].map((t) => h.html`<button type="button" data-transport="${t}" aria-pressed="${t === d.transport}">${t}</button>`)}</span>
        <button type="button" class="dk-btn" data-import>⬆ Importer…</button>
        <button type="button" class="dk-btn" data-export>⬇ Exporter vers Postman</button>
        <button type="button" class="dk-btn primary" data-run>▶ Exécuter la campagne</button>
      </div>
    </header>
    <div class="tnr-kpis">${d.kpis.map((k) => h.render('tnr.dash.kpi', k))}</div>
    <div class="tnr-grid">
      <section class="tnr-card wide"><h3>Collection <small>${d.collectionMeta}</small><input type="search" data-filter placeholder="Filtrer : méthode, nom, chemin…" value="${d.query || ''}"></h3>${d.folders.length ? h.raw(d.folders) : h.html`<p class="tnr-none">Aucune collection : Fichier › Importer ▸ Collection Postman.</p>`}</section>
      <section class="tnr-card"><h3>Scénarios <small>${d.scenarioMeta}</small></h3><ul class="tnr-scens">${h.raw(d.scenarios)}</ul></section>
      <section class="tnr-card"><h3>Environnement <small>${d.environment}</small><button type="button" class="dk-btn" data-save-env title="Garder les valeurs courantes comme valeurs de l’environnement (Ctrl+Z pour annuler)" ${d.changed ? '' : 'disabled'}>Enregistrer ${d.changed ? `(${d.changed})` : ''}</button></h3>
        <table class="tnr-env"><thead><tr><th>Variable</th><th>Initiale</th><th>Courante</th></tr></thead><tbody>${h.raw(d.vars)}</tbody></table></section>
      <section class="tnr-card"><h3>Derniers échecs <small>${d.failureMeta}</small></h3>${d.failures.length ? h.html`<ul class="tnr-fails">${d.failures.map((f) => h.html`<li data-go="${f.dominoId}">${h.render('report.status', f)}<b>${f.title}</b><small>${f.where}</small><span>${f.summary}</span></li>`)}</ul>` : h.html`<p class="tnr-none">${d.ran ? 'Aucun échec à la dernière exécution.' : 'Pas encore exécutée.'}</p>`}</section>
    </div>
  </div>`,
  { description: 'Le tableau de bord TNR : environnement, transport, import/export, chiffres clés, collection (dossiers, sous-dossiers, requêtes, couverture), scénarios, variables, échecs.', data: '{ name, subtitle, environments, environment, transport, kpis, folders (HTML), collectionMeta, scenarios (HTML), scenarioMeta, vars (HTML), changed, failures, failureMeta, ran, query }' });
})(typeof globalThis !== 'undefined' ? globalThis : window);
