/*!
 * Démo · Éditeur de workflow
 * Le scénario « Onboarding client » dépend de deux autres scénarios (KYC et solvabilité),
 * rangés dans le composant « Vérifications » et appelés par une seule pierre.
 */
(function (root) {
  'use strict';
  const D = root.Domino;

  const types = [
    { name: 'event', label: 'Événement', color: '#EE7D2F', description: 'Ce qui déclenche le scénario.' },
    { name: 'client', label: 'Client', color: '#3B7DDD', description: 'La fiche client, enrichie étape par étape.' },
    { name: 'verdict', label: 'Verdict', color: '#E2A812', description: 'Le résultat des vérifications.' },
    { name: 'check', label: 'Contrôle', color: '#13A3A0', description: 'Le résultat d’un contrôle (ok, score).' },
    { name: 'score', label: 'Score', color: '#6A5BDC', description: 'Une note chiffrée.' },
    { name: 'message', label: 'Message', color: '#38A169', description: 'Un e-mail, une notification.' },
    { name: 'provider', label: 'Fournisseur', color: '#D9539A', description: 'Un service externe.' },
  ];

  const dominos = [
    {
      type: 'wf.webhook', name: 'Nouveau client', category: 'Déclencheurs',
      description: 'Déclencheur (0 | 1) : commence le scénario.',
      right: [{ name: 'événement', type: 'event' }],
      fields: { source: { kind: 'text', label: 'Source', default: 'formulaire web' } },
      run: (rc) => [{ source: rc.fields.source, client: rc.ctx.get('client') }],
    },
    {
      type: 'wf.normalize', name: 'Normaliser', category: 'Données',
      left: [{ name: 'événement', type: 'event' }], right: [{ name: 'client', type: 'client' }],
      run: (rc) => { const c = (rc.inputs[0] || {}).client || {}; return [{ ...c, name: String(c.name || '').trim(), email: String(c.email || '').trim().toLowerCase() }]; },
    },
    {
      type: 'wf.checks', name: 'Vérifications', category: 'Composants', container: { kind: 'Composant' },
      description: 'Composant : ses deux scénarios (KYC et solvabilité) tournent dans sa sous-partie. « Ouvrir la partie » dans sa fiche, ou Maj + double-clic.',
      left: [{ name: 'client', type: 'client' }], right: [{ name: 'verdict', type: 'verdict' }],
      run: async (rc) => {
        const r = await rc.runPartie([rc.inputs[0]]);
        const approved = !!(r.kyc && r.kyc.ok && r.credit && r.credit.ok);
        rc.log(approved ? 'info' : 'warn', `vérifications : KYC ${r.kyc && r.kyc.ok ? 'ok' : 'refusé'}, solvabilité ${r.credit && r.credit.ok ? 'ok' : 'refusée'}`);
        return [{ approved, kyc: r.kyc, credit: r.credit, client: rc.inputs[0] }];
      },
    },
    {
      type: 'wf.kyc', name: 'Vérifier l’identité', category: 'Contrôles',
      left: [{ name: 'client', type: 'client' }, { name: 'fournisseur', type: 'provider' }], right: [{ name: 'contrôle', type: 'check' }],
      run: (rc) => { const [c, p] = rc.inputs; if (!p) throw new Error('aucun fournisseur KYC : collez-en un en adjacente haute.'); return [{ ok: !!(c && c.idDoc), provider: p.name, client: c }]; },
    },
    {
      type: 'wf.idscore', name: 'Score d’identité', category: 'Contrôles',
      left: [{ name: 'contrôle', type: 'check' }], right: [{ name: 'contrôle', type: 'check' }],
      fields: { min: { kind: 'number', label: 'Minimum', default: { $bind: 'rules.minIdScore' } } },
      run: (rc) => { const c = rc.inputs[0] || {}; const score = c.ok ? 0.92 : 0.2; return [{ ...c, score, ok: c.ok && score >= rc.fields.min }]; },
    },
    {
      type: 'wf.bureau', name: 'Interroger la centrale', category: 'Contrôles',
      left: [{ name: 'client', type: 'client' }], right: [{ name: 'score', type: 'score' }],
      run: (rc) => [Math.round(300 + ((rc.inputs[0] || {}).income || 0) / 10)],
    },
    {
      type: 'wf.credit', name: 'Décider la solvabilité', category: 'Contrôles',
      left: [{ name: 'score', type: 'score' }, { name: 'seuil', type: 'score' }], right: [{ name: 'contrôle', type: 'check' }],
      run: (rc) => { const [s, min] = rc.inputs; return [{ ok: s >= min, score: s, min }]; },
    },
    {
      type: 'wf.decide', name: 'Si validé', category: 'Logique',
      description: 'Deux sorties : accepté (la suite) ou refusé (une branche).',
      left: [{ name: 'verdict', type: 'verdict' }], right: [{ name: 'accepté', type: 'client' }, { name: 'refusé', type: 'verdict' }],
      run: (rc) => { const v = rc.inputs[0] || {}; return v.approved ? [v.client, undefined] : [undefined, v]; },
    },
    {
      type: 'wf.account', name: 'Créer le compte', category: 'Actions',
      left: [{ name: 'client', type: 'client' }], right: [{ name: 'client', type: 'client' }],
      run: (rc) => [{ ...rc.inputs[0], accountId: 'A-1042' }],
    },
    {
      type: 'wf.email', name: 'E-mail de bienvenue', category: 'Actions',
      left: [{ name: 'client', type: 'client' }, { name: 'modèle', type: 'message' }], right: [{ name: 'envoyé', type: 'message' }],
      run: (rc) => { const [c, tpl] = rc.inputs; return [{ to: c.email, subject: tpl ? tpl.subject : 'Bienvenue', sent: true }]; },
    },
    {
      type: 'wf.wait', name: 'Attendre', category: 'Logique',
      left: [{ name: 'message', type: 'message' }], right: [{ name: 'message', type: 'message' }],
      fields: { duration: { kind: 'select', label: 'Durée', options: ['1 jour', '2 jours', '7 jours'], default: '2 jours', bindable: false } },
      title: (api) => `Attendre ${api.field('duration')}`,
      run: (rc) => [rc.inputs[0]],
    },
    {
      type: 'wf.followup', name: 'Relancer si inactif', category: 'Actions',
      left: [{ name: 'message', type: 'message' }], right: [{ name: 'message', type: 'message' }],
      run: (rc) => [{ ...rc.inputs[0], followUp: true }],
    },
    {
      type: 'wf.crm', name: 'Mettre à jour le CRM', category: 'Actions',
      description: 'Terminale : rien ne la suit.',
      left: [{ name: 'message', type: 'message' }],
      run: (rc) => { rc.ctx.set('crm.lastUpdate', { status: 'onboarded', at: '2026-10-18' }); return []; },
    },
    {
      type: 'wf.notify', name: 'Notifier la conformité', category: 'Actions',
      left: [{ name: 'verdict', type: 'verdict' }], right: [{ name: 'message', type: 'message' }],
      run: (rc) => [{ text: `Dossier refusé : KYC ${rc.inputs[0].kyc && rc.inputs[0].kyc.ok ? 'ok' : 'non'}, solvabilité ${rc.inputs[0].credit && rc.inputs[0].credit.ok ? 'ok' : 'non'}.` }],
    },
    {
      type: 'src.template', name: 'Modèle e-mail', category: 'Sources',
      right: [{ name: 'modèle', type: 'message' }],
      fields: { subject: { kind: 'text', label: 'Objet', default: 'Bienvenue {{client.name}} !' } },
      run: (rc) => [{ subject: rc.fields.subject }],
    },
    {
      type: 'src.kyc', name: 'Fournisseur KYC', category: 'Sources',
      right: [{ name: 'fournisseur', type: 'provider' }],
      fields: { name: { kind: 'select', label: 'Service', options: ['Onfido', 'Veriff', 'Ubble'], default: 'Ubble', bindable: false } },
      title: (api) => `KYC ${api.field('name')}`,
      run: (rc) => [{ name: rc.fields.name }],
    },
    {
      type: 'obs.audit', name: 'Journal d’audit', category: 'Observabilité',
      left: [{ name: 'entrée', type: 'any' }],
      run: (rc) => { rc.log('info', `audit : ${JSON.stringify(rc.inputs[0]).slice(0, 90)}`); return []; },
    },
    {
      type: 'obs.slack', name: 'Slack', category: 'Observabilité',
      left: [{ name: 'message', type: 'message' }],
      fields: { channel: { kind: 'text', label: 'Canal', default: '#conformité' } },
      title: (api) => `Slack ${api.field('channel')}`,
      run: (rc) => { rc.log('info', `Slack ${rc.fields.channel} : ${(rc.inputs[0] || {}).text}`); return []; },
    },
  ];

  const project = {
    format: 'kantoaplo.domino', version: 1,
    editor: { id: 'workflow', name: 'Éditeur de workflow' },
    name: 'Onboarding client',
    context: {
      client: { name: 'Ada Lovelace', email: '  ADA@Example.com ', idDoc: true, income: 4200 },
      rules: { minScore: 600, minIdScore: 0.8 },
    },
    parties: [
      {
        id: 'main', name: 'Onboarding client',
        dominos: [{
          id: 'w1', type: 'wf.webhook',
          next: [{ pip: 0, domino: {
            id: 'w2', type: 'wf.normalize',
            next: [{ pip: 0, domino: {
              id: 'ck', type: 'wf.checks',
              next: [{ pip: 0, domino: {
                id: 'w4', type: 'wf.decide',
                next: [
                  { pip: 0, label: 'accepté', domino: {
                    id: 'w5', type: 'wf.account', turn: 'down', bottom: [{ pip: 0, domino: { id: 'au', type: 'obs.audit' } }],
                    next: [{ pip: 0, domino: {
                      id: 'w6', type: 'wf.email', top: [{ pip: 1, domino: { id: 'tp', type: 'src.template' } }],
                      next: [{ pip: 0, domino: {
                        id: 'w7', type: 'wf.wait', fields: { duration: '2 jours' }, turn: 'left',
                        next: [{ pip: 0, domino: {
                          id: 'w8', type: 'wf.followup',
                          next: [{ pip: 0, domino: { id: 'w9', type: 'wf.crm' } }],
                        } }],
                      } }],
                    } }],
                  } },
                  { pip: 1, label: 'refusé', domino: { id: 'w10', type: 'wf.notify', bottom: [{ pip: 0, domino: { id: 'sl', type: 'obs.slack' } }] } },
                ],
              } }],
            } }],
          } }],
        }],
      },
      {
        id: 'ck', owner: 'ck', name: 'Vérifications',
        dominos: [
          {
            id: 'e1', type: 'domino.entry', label: 'KYC',
            next: [{ pip: 0, domino: {
              id: 'k1', type: 'wf.kyc', top: [{ pip: 1, domino: { id: 'pv', type: 'src.kyc' } }],
              next: [{ pip: 0, domino: {
                id: 'k2', type: 'wf.idscore', fields: { min: { $bind: 'rules.minIdScore' } },
                next: [{ pip: 0, domino: { id: 'x1', type: 'domino.exit', fields: { name: 'kyc' } } }],
              } }],
            } }],
          },
          {
            id: 'e2', type: 'domino.entry', label: 'Solvabilité',
            next: [{ pip: 0, domino: {
              id: 'b1', type: 'wf.bureau',
              next: [{ pip: 0, domino: {
                id: 'b2', type: 'wf.credit', top: [{ pip: 1, domino: { id: 'th', type: 'ctx.get', fields: { path: 'rules.minScore' } } }],
                next: [{ pip: 0, domino: { id: 'x2', type: 'domino.exit', fields: { name: 'credit' } } }],
              } }],
            } }],
          },
        ],
      },
    ],
  };

  // ---------------------------------------------------------------------------
  // Générateurs
  // ---------------------------------------------------------------------------
  const slug = (s) => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
  const title = (n) => n.label || ({ 'wf.webhook': 'Nouveau client', 'wf.normalize': 'Normaliser', 'wf.checks': 'Vérifications', 'wf.decide': 'Si validé', 'wf.account': 'Créer le compte', 'wf.email': 'E-mail de bienvenue', 'wf.wait': `Attendre ${n.fields && n.fields.duration}`, 'wf.followup': 'Relancer si inactif', 'wf.crm': 'Mettre à jour le CRM', 'wf.notify': 'Notifier la conformité', 'wf.kyc': 'Vérifier l’identité', 'wf.idscore': 'Score d’identité', 'wf.bureau': 'Interroger la centrale', 'wf.credit': 'Décider la solvabilité', 'domino.entry': 'Entrée', 'domino.exit': `Résultat ${n.fields && n.fields.name}` })[n.type] || n.type;

  const yaml = new D.Generator('yaml', { label: 'Workflow YAML', extension: 'yaml' }).on('project', (json, g) => {
    const main = json.parties.find((p) => p.id === 'main');
    const lines = [`name: ${json.name}`, 'on:', `  webhook: ${main.dominos[0].fields ? main.dominos[0].fields.source : 'formulaire web'}`, 'jobs:'];
    const comps = json.parties.filter((p) => p.owner);
    for (const c of comps) {
      for (const head of c.dominos) {
        const id = slug(head.label || head.id);
        lines.push(`  ${id}:`, `    component: ${c.name}`, '    steps:');
        for (let n = g.next(head, 0); n; n = g.next(n, 0)) {
          if (n.type === 'domino.exit') { lines.push(`      - output: ${n.fields.name}`); continue; }
          lines.push(`      - name: ${title(n)}`, `        uses: ${n.type}`);
          for (const a of n.top || []) lines.push(`        with: { ${a.domino.type === 'ctx.get' ? `seuil: \${{ ${a.domino.fields.path} }}` : `${slug(title(a.domino) || a.domino.type)}: ${a.domino.fields ? Object.values(a.domino.fields)[0] : ''}`} }`);
        }
      }
    }
    lines.push('  onboarding:', `    needs: [${comps.flatMap((c) => c.dominos.map((h) => slug(h.label || h.id))).join(', ')}]`, '    steps:');
    const walk = (n, ind, cond) => {
      for (; n; n = g.next(n, 0)) {
        lines.push(`${ind}- name: ${title(n)}`, `${ind}  uses: ${n.type}`);
        if (cond) { lines.push(`${ind}  if: ${cond}`); cond = null; }
        for (const b of n.bottom || []) lines.push(`${ind}  then: ${b.domino.type}`);
        const alt = (n.next || []).filter((l) => l.pip > 0);
        for (const l of alt) { lines.push(`${ind}  else:`); walk(l.domino, ind + '    ', null); }
        if (n.type === 'wf.decide') cond = 'verdict.approved';
      }
    };
    walk(main.dominos[0], '      ', null);
    return lines.join('\n');
  });

  const mermaid = new D.Generator('mermaid', { label: 'Diagramme Mermaid', extension: 'mmd' }).on('project', (json) => {
    const out = ['flowchart LR'];
    const node = (n) => `${n.id}["${title(n).replace(/"/g, "'")}"]`;
    const edges = (n) => {
      for (const l of n.next || []) { out.push(`  ${node(n)} -->${l.label ? `|${l.label}|` : ''} ${node(l.domino)}`); edges(l.domino); }
      for (const a of n.top || []) out.push(`  ${a.domino.id}(["${a.domino.type === 'ctx.get' ? a.domino.fields.path : title(a.domino)}"]) -.-> ${n.id}`);
      for (const b of n.bottom || []) out.push(`  ${n.id} -.-> ${b.domino.id}(["${b.domino.type}"])`);
    };
    for (const p of json.parties) {
      if (p.owner) out.push(`  subgraph sub_${p.id}["Composant ${p.name}"]`);
      for (const h of p.dominos) edges(h);
      if (p.owner) { out.push('  end'); out.push(`  ${p.owner} -. appelle .-> sub_${p.id}`); }
    }
    return out.join('\n');
  });

  D.packs.workflow = {
    id: 'workflow', name: 'Éditeur de workflow', color: '#EE7D2F',
    description: 'Un scénario qui dépend de deux autres, rangés dans un composant appelé par une pierre.',
    types, dominos, project, context: project.context,
    generators: [yaml, mermaid],
    options: { table: 1150 },
    inspector: {
      tabs: [{
        id: 'deps', title: 'Dépendances',
        help: 'Exemple d’onglet métier : de quels scénarios dépend le scénario principal',
        onEvent: (ev) => ['change', 'run:end', 'load'].includes(ev.type),
        render: (el, insp) => {
          const ws = insp.ws, last = insp.ed.runtime.last;
          const status = (id) => { const s = last && [...last.trace].reverse().find((x) => x.dominoId === id); return s ? (s.status === 'ok' ? '<span style="color:var(--ok)">ok</span>' : s.status === 'error' ? '<span style="color:var(--err)">erreur</span>' : '<span style="color:var(--ink-3)">sauté</span>') : '<span style="color:var(--ink-3)">—</span>'; };
          const comps = [...ws.nodes.values()].filter((n) => n.def.container);
          const rows = [];
          for (const c of comps) {
            for (const head of ws.roots(c.id)) {
              const chain = [];
              for (let n = head; n; n = n.next[0] && ws.get(n.next[0].id)) chain.push(n);
              const exit = chain.find((n) => n.type === 'domino.exit');
              rows.push(`<tr><td>${insp.link(head.id, ws.titleOf(head))}</td><td>${insp.link(c.id)} <span style="color:var(--ink-3)">(${insp.esc(c.def.container.kind)})</span></td><td>${chain.length}</td><td><code>${exit ? insp.esc(exit.fields.name) : '—'}</code></td><td>${exit ? status(exit.id) : '—'}</td></tr>`);
            }
          }
          const waits = [...ws.nodes.values()].filter((n) => n.type === 'wf.wait').map((n) => parseInt(n.fields.duration, 10) || 0);
          el.innerHTML = `<div class="dk-pane"><div class="dk-toolbar"><b style="font-size:12px">« ${insp.esc(ws.name)} » dépend de ${rows.length} scénarios</b><span style="color:var(--ink-3);font-size:11.5px">Ils tournent dans la sous-partie du composant ; le scénario principal attend leurs résultats (pierres « Résultat de la partie »). Délai prévu : ${waits.reduce((a, b) => a + b, 0)} jour(s).</span></div>
            <table class="dk-table"><thead><tr><th>scénario</th><th>dans le composant</th><th>pierres</th><th>rend</th><th>dernier passage</th></tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
          insp.wire(el);
        },
      }],
    },
  };
})(typeof globalThis !== 'undefined' ? globalThis : window);
