/*!
 * Démo · Scénarios d'API (TNR) : le tableau de bord (une projection du projet)
 *
 *   D.TNR.dashboard(ws, dernièreExécution)   les données, sans DOM : chiffres clés, couverture de la collection
 *                                            par dossier, scénarios et leur statut, variables, échecs
 *   projection « tnr.dashboard »             l'affichage (gabarits tnr.dash.*), réservé au langage « tnr »
 */
(function (root) {
  'use strict';
  const D = root.Domino;
  const P = D.Postman;
  const TNR = D.TNR;

  /** Les données du tableau de bord. */
  function dashboard(ws, last) {
    const col = ws.assets.get(TNR.COLLECTION);
    const cat = col ? P.catalog(col) : null;
    const reports = (last && last.reports) || [];
    // Couverture : les pierres « Requête » qui viennent de chaque requête de la collection (ref), ou de même méthode et chemin.
    const requests = [...ws.nodes.values()].filter((n) => n.type === 'tnr.request');
    const coveredBy = new Map();
    for (const n of requests) {
      const r = cat && (cat.requests.find((x) => x.id === n.fields.ref) || cat.requests.find((x) => x.method === n.fields.method && x.path === P.pathOf(n.fields.url)));
      if (r) coveredBy.set(r.id, [...(coveredBy.get(r.id) || []), n.id]);
    }
    // Le dernier statut de chaque requête de la collection (la dernière fois qu'une de ses pierres a tourné).
    const lastOf = new Map();
    for (const e of reports) if (e.kind === 'tnr.http' && e.details && e.details.ref) lastOf.set(e.details.ref, e);
    const scenarios = [...ws.nodes.values()].filter((n) => n.type === 'tnr.scenario');
    const scenReports = new Map(reports.filter((e) => e.kind === 'tnr.scenario').map((e) => [e.dominoId, e]));
    const checks = reports.filter((e) => e.kind === 'tnr.assert');
    const http = reports.filter((e) => e.kind === 'tnr.http');
    const pass = checks.filter((e) => e.status === 'ok').length, fail = checks.filter((e) => e.status !== 'ok').length;
    const errors = http.filter((e) => e.status === 'error').length;
    const avg = http.length ? Math.round(http.reduce((s, e) => s + (e.ms || 0), 0) / http.length) : null;
    const covered = cat ? cat.requests.filter((r) => coveredBy.has(r.id)).length : 0;
    // L'environnement : initial (la ressource) et courant (le contexte, après exécution).
    const s = TNR.settings(ws);
    const envName = ws.context.get('tnr.environment') || s.environment;
    const envDef = TNR.environments(ws).find((e) => e.name === envName) || TNR.environments(ws)[0];
    const initial = envDef ? P.readEnvironment(envDef).values : {};
    const current = ws.context.get('env') || {};
    const m = TNR.masker(ws, ws.context);
    const vars = [...new Set([...Object.keys(initial), ...Object.keys(current)])].map((key) => {
      const secret = m.isSecret(key), show = (v) => (v == null || v === '' ? '—' : secret ? `••••${String(v).slice(-3)}` : String(v).length > 40 ? `${String(v).slice(0, 39)}…` : String(v));
      return { key, initial: show(initial[key]), current: show(current[key]), changed: String(initial[key] ?? '') !== String(current[key] ?? ''), secret };
    });
    const tree = (f) => f.items.map((x) => (x.kind === 'folder'
      ? { kind: 'folder', name: x.name, description: x.description, items: tree(x) }
      : { kind: 'request', id: x.id, method: x.method, color: P.METHOD_COLOR[x.method], name: x.name, path: x.path, url: x.url, description: x.description, covered: (coveredBy.get(x.id) || []).length, nodes: coveredBy.get(x.id) || [], last: lastOf.get(x.id) }));
    const failures = reports.filter((e) => e.status === 'fail' || e.status === 'error').filter((e) => e.kind !== 'tnr.scenario').map((e) => ({ ...e, where: (e.path || []).slice(1).join(' › ') || 'Campagne' }));
    return {
      name: (cat && cat.name) || ws.name, description: cat ? cat.description : '',
      environments: TNR.environments(ws).map((e) => e.name), environment: envDef ? envDef.name : '', transport: s.transport,
      counts: { requests: cat ? cat.requests.length : 0, folders: cat ? cat.folders.length : 0, scenarios: scenarios.length, covered, pass, fail, errors, http: http.length, avg },
      tree: cat ? tree(cat.root) : [],
      scenarios: scenarios.map((n) => { const r = scenReports.get(n.id); const steps = ws.nodesOf(n.id).filter((x) => x.type === 'tnr.request').length; return { id: n.id, name: n.fields.name, status: r ? r.status : n.fields.skip ? 'skip' : 'idle', meta: r ? r.summary : `${steps} requête${steps > 1 ? 's' : ''}${n.fields.skip ? ' · ignoré' : ''}`, ms: r ? r.ms : null }; }),
      vars, changed: vars.filter((v) => v.changed).length, failures, ran: !!last, at: last ? last.startedAt : null,
    };
  }
  TNR.dashboard = dashboard;

  if (!D.Projections || typeof document === 'undefined') return;
  const T = () => D.Templates;
  const codeOf = (e) => (!e ? null : e.status === 'error' ? { text: 'erreur', cls: 'err' } : { text: String((/→ (\d{3})/.exec(e.summary) || [])[1] || e.status), cls: e.status === 'ok' ? 'ok' : 'warn' });

  D.Projections.register({
    id: 'tnr.dashboard', language: 'tnr', label: 'Tableau de bord', icon: '◧',
    description: 'La collection (dossiers, sous-dossiers, requêtes, couverture), les scénarios, l’environnement, les échecs ; exécuter, importer, exporter.',
    mount(host, ed) {
      const ws = ed.ws;
      let query = '', raf = 0;
      const open = new Set();
      const self = {
        refresh() { if (raf) return; raf = requestAnimationFrame(() => { raf = 0; render(); }); },
        destroy() { cancelAnimationFrame(raf); offs.forEach((f) => f()); host.innerHTML = ''; },
      };
      const offs = [ws.on('change', () => self.refresh()), ws.on('load', () => self.refresh()), ws.on('asset', () => self.refresh()), ws.on('context', () => self.refresh()), ws.on('run:end', () => self.refresh()), ws.on('run:report', () => self.refresh())];
      function render() {
        const d = dashboard(ws, ed.runtime.last), c = d.counts;
        const q = query.trim().toLowerCase();
        const match = (r) => !q || `${r.method} ${r.name} ${r.path}`.toLowerCase().includes(q);
        const folder = (name, description, items, depth) => {
          const reqs = [], subs = [];
          let total = 0, cov = 0;
          for (const x of items) {
            if (x.kind === 'folder') { const f = folder(x.name, x.description, x.items, depth + 1); if (f) { subs.push(f.html); total += f.total; cov += f.cov; } }
            else if (match(x)) { total++; if (x.covered) cov++; reqs.push(T().render('tnr.dash.request', { ...x, last: codeOf(x.last) })); }
          }
          if (!total) return null;
          const key = `${depth}:${name}`;
          return { total, cov, html: T().render('tnr.dash.folder', { name, description, count: `${total} requête${total > 1 ? 's' : ''}`, coverage: Math.round((cov / total) * 100), open: !!q || open.has(key), body: reqs.join('') + subs.map((h) => `<li class="tnr-sub">${h}</li>`).join(''), key }).replace('<details class="tnr-folder"', `<details class="tnr-folder" data-key="${key.replace(/"/g, '&quot;')}"`) };
        };
        const loose = d.tree.filter((x) => x.kind === 'request');
        const folders = [...(loose.length ? [folder('Hors dossier', '', loose, 0)] : []), ...d.tree.filter((x) => x.kind === 'folder').map((f) => folder(f.name, f.description, f.items, 0))].filter(Boolean).map((f) => f.html).join('');
        const pct = c.requests ? Math.round((c.covered / c.requests) * 100) : 0;
        const kpis = [
          { label: 'requêtes dans la collection', value: c.requests, sub: `${c.folders} dossiers` },
          { label: 'scénarios', value: c.scenarios },
          { label: 'couverture', value: `${pct} %`, sub: `${c.covered}/${c.requests} requêtes`, tone: pct >= 80 ? 'ok' : pct >= 40 ? 'warn' : 'fail', help: 'La part des requêtes de la collection qui figurent dans au moins un scénario.' },
          { label: 'vérifications réussies', value: d.ran ? `${c.pass}/${c.pass + c.fail}` : '—', tone: d.ran ? (c.fail ? 'fail' : 'ok') : '', sub: d.ran ? `${c.fail} échec${c.fail > 1 ? 's' : ''}` : 'pas encore exécutée' },
          { label: 'requêtes envoyées', value: d.ran ? c.http : '—', sub: d.ran && c.errors ? `${c.errors} erreur${c.errors > 1 ? 's' : ''} réseau` : d.ran ? 'aucune erreur réseau' : '', tone: c.errors ? 'fail' : '' },
          { label: 'temps moyen', value: c.avg != null ? `${c.avg} ms` : '—', sub: d.at ? new Date(d.at).toLocaleTimeString() : '' },
        ];
        const scenFocus = host.contains(document.activeElement) && document.activeElement.matches('[data-filter]');
        host.innerHTML = T().render('tnr.dashboard', {
          ...d, query, kpis, folders,
          subtitle: d.description ? d.description.split('\n')[0] : 'Collection, scénarios, environnement et résultats de la dernière exécution.',
          collectionMeta: `${c.requests} requêtes · ${c.folders} dossiers · ${pct} % couvertes`,
          scenarios: d.scenarios.map((x) => T().render('tnr.dash.scenario', x)).join(''),
          scenarioMeta: `${d.scenarios.filter((x) => x.status === 'ok').length}/${d.scenarios.length} réussis`,
          vars: d.vars.map((v) => T().render('tnr.dash.var', v)).join(''),
          failureMeta: d.ran ? `${d.failures.length}` : '',
        });
        if (scenFocus) { const i = host.querySelector('[data-filter]'); i.focus(); i.setSelectionRange(i.value.length, i.value.length); }
      }
      host.addEventListener('toggle', (e) => { const det = e.target.closest && e.target.closest('details[data-key]'); if (det) { if (det.open) open.add(det.dataset.key); else open.delete(det.dataset.key); } }, true);
      host.addEventListener('input', (e) => { if (e.target.matches('[data-filter]')) { query = e.target.value; render(); } });
      host.addEventListener('change', (e) => {
        if (!e.target.matches('[data-env]')) return;
        const name = e.target.value;
        TNR.activateEnvironment(ws, name);
        const c = TNR.settings(ws).campaign;
        if (c) ws.setField(c.id, 'environment', name);
        ed.toast(`Environnement « ${name} » chargé.`, 'ok');
      });
      host.addEventListener('click', async (e) => {
        const t = e.target.closest('[data-run],[data-export],[data-import],[data-save-env],[data-transport],[data-open],[data-go],[data-ref]');
        if (!t) return;
        if (t.matches('[data-run]')) { ed.run({ partie: 'main' }); return; }
        if (t.matches('[data-transport]')) { const c = TNR.settings(ws).campaign; if (c) ws.setField(c.id, 'transport', t.dataset.transport); else ed.toast('Posez une pierre « Campagne » sur la table principale.', 'warn'); return; }
        if (t.matches('[data-export]')) {
          const out = await D.Codegen.runAsync('tnr/postman', ws);
          for (const f of out.files) if (D.UI && D.UI.download) await D.UI.download(f.path, f.content, f.mime);
          ed.toast(`${out.files.length} fichier(s) exporté(s) : collection et environnement(s), à importer dans Postman.`, 'ok');
          return;
        }
        if (t.matches('[data-import]')) {
          if (!D.UI || !D.UI.pickFile) return;
          const f = await D.UI.pickFile();
          if (!f) return;
          try {
            const json = JSON.parse(f.text);
            const imp = D.Importers.detect(json, f.name);
            if (!imp) { ed.toast('Ce fichier n’est ni une collection ni un environnement Postman.', 'err'); return; }
            const r = D.Importers.run(imp.id, json, { ws, name: f.name });
            if (r.applied) ed.toast(r.summary, 'ok'); else ed.toast('Une autre collection : ouvrez-la par Fichier › Importer ▸ (un nouveau projet).', 'warn');
          } catch (err) { ed.toast(err.message, 'err'); }
          return;
        }
        if (t.matches('[data-save-env]')) {
          const name = ws.context.get('tnr.environment');
          const list = TNR.environments(ws).map((x) => (x.name !== name ? x : { ...x, values: P.exportEnvironment(x, ws.context.get('env') || {}).values }));
          ws.setAsset(TNR.ENVIRONMENTS, list, 'Enregistrer l’environnement');
          ed.toast(`Environnement « ${name} » enregistré (Ctrl+Z pour annuler).`, 'ok');
          return;
        }
        if (t.matches('[data-open]')) { ed.project('dominos'); ed.openPartie(t.dataset.open); return; }
        const id = t.dataset.go || null;
        if (id && ws.get(id)) { ed.project('dominos'); ed.select(id); return; }
        if (t.matches('[data-ref]')) {
          const d = dashboard(ws, null), find = (items) => { for (const x of items) { if (x.kind === 'folder') { const r = find(x.items); if (r) return r; } else if (x.id === t.dataset.ref) return x; } return null; };
          const r = find(d.tree);
          if (r && r.nodes.length) { ed.project('dominos'); ed.select(r.nodes[0]); ed.toast(`« ${r.name} » : ${r.nodes.length} pierre(s) dans les scénarios.`, 'ok'); }
          else ed.toast(`« ${r ? r.name : '?'} » n’est dans aucun scénario : glissez-la depuis la boîte à outils (Collection) dans un scénario.`, 'warn');
        }
      });
      render();
      return self;
    },
  });
})(typeof globalThis !== 'undefined' ? globalThis : window);
