/*!
 * Langage · Flux (outil d'automatisation)
 * La même plateforme, d'autres choix : pas de classes, mais des « connecteurs » (des bibliothèques,
 * dont une vient d'un autre projet) et des « sous-flux » (des fonctions). Les appels aux services sont
 * asynchrones ; chaque fil dit si le flux attend la réponse ou continue. Une règle propre au langage
 * interdit de relier un déclencheur par un fil.
 * Générateurs : un workflow JSON (pour un moteur d'exécution) et un diagramme de séquence Mermaid
 * où l'on voit les appels bloquants (->>) et non bloquants (-)).
 */
(function (root) {
  'use strict';
  const D = root.Domino;

  const types = [
    { name: 'événement', label: 'Événement', color: '#EE7D2F', description: 'Ce qui déclenche le flux.' },
    { name: 'contact', label: 'Contact', color: '#3B7DDD', description: 'Une personne : nom, e-mail, client connu ou non.' },
    { name: 'message', label: 'Message', color: '#38A169', description: 'Un texte à envoyer.' },
    { name: 'fonction', label: 'Action d’un connecteur', color: '#5E6E7A', kind: 'call', description: 'Une action offerte par un connecteur (Slack, e-mail, CRM…).' },
  ];

  const dominos = [
    {
      type: 'a.trigger', name: 'Formulaire reçu', category: 'Déclencheurs', kind: 'déclencheur',
      description: 'Déclencheur : lit l’événement dans le contexte.',
      right: [{ name: 'événement', type: 'événement' }],
      fields: { form: { kind: 'text', label: 'Formulaire', default: 'contact-site', bindable: false } },
      title: (api) => `Formulaire « ${api.field('form')} »`,
      run: (rc) => [rc.ctx.get('événement')],
    },
    {
      type: 'a.extract', name: 'Extraire le contact', category: 'Données',
      left: [{ name: 'événement', type: 'événement' }], right: [{ name: 'contact', type: 'contact' }],
      run: (rc) => { const e = rc.inputs[0] || {}; return [{ nom: String(e.nom || '').trim(), email: String(e.email || '').trim().toLowerCase() }]; },
    },
    {
      type: 'a.lookup', name: 'Chercher dans la base', category: 'Données', async: true,
      description: 'Asynchrone : regarde si l’e-mail est déjà dans la base (contexte « base »).',
      left: [{ name: 'contact', type: 'contact' }], right: [{ name: 'contact', type: 'contact' }],
      run: async (rc) => { await rc.sleep(200); const c = rc.inputs[0] || {}; return [{ ...c, connu: (rc.ctx.get('base') || []).includes(c.email), clé: rc.self && rc.self.props.clé }]; },
    },
    {
      type: 'a.if', name: 'Si client connu', category: 'Logique', kind: 'logique',
      left: [{ name: 'contact', type: 'contact' }], right: [{ name: 'oui', type: 'contact' }, { name: 'non', type: 'contact' }],
      run: (rc) => (rc.inputs[0] && rc.inputs[0].connu ? [rc.inputs[0], undefined] : [undefined, rc.inputs[0]]),
    },
    {
      type: 'a.write', name: 'Rédiger', category: 'Messages',
      description: 'Écrit un message : {nom} et {email} viennent du contact.',
      left: [{ name: 'contact', type: 'contact' }], right: [{ name: 'message', type: 'message' }],
      fields: { tpl: { kind: 'text', label: 'Modèle', default: 'Bonjour {nom}' } },
      title: (api) => `« ${api.field('tpl')} »`,
      run: (rc) => { const c = rc.inputs[0] || {}; return [String(rc.fields.tpl).replace(/\{(\w+)\}/g, (_, k) => c[k] ?? '')]; },
    },
    {
      type: 'a.wait', name: 'Attendre', category: 'Logique', kind: 'logique', async: true,
      left: [{ name: 'valeur', type: 'any' }], right: [{ name: 'valeur', type: 'any' }],
      fields: { ms: { kind: 'number', label: 'Durée (ms)', default: 300, bindable: false } },
      title: (api) => `Attendre ${api.field('ms')} ms`,
      run: async (rc) => { await rc.sleep(Number(rc.fields.ms)); return [rc.inputs[0]]; },
    },
    {
      type: 'a.post', name: 'Envoyer', category: 'Messages', kind: 'action',
      description: 'Envoie le message sur un canal (noté dans le contexte « envois »).',
      left: [{ name: 'message', type: 'message' }], right: [{ name: 'accusé', type: 'message' }],
      fields: { canal: { kind: 'text', label: 'Canal', default: 'E-mail', bindable: false } },
      title: (api) => `Envoyer · ${api.field('canal')}`,
      run: (rc) => { const line = `[${rc.fields.canal}] ${rc.inputs[0]}`; rc.ctx.set('envois', [...(rc.ctx.get('envois') || []), line]); rc.log('info', line); return [`envoyé : ${rc.fields.canal}`]; },
    },
    {
      type: 'a.audit', name: 'Journal d’audit', category: 'Suivi', kind: 'action',
      description: 'Terminale : note ce qu’elle reçoit. Posée libre, un fil la déclenche.',
      left: [{ name: 'entrée', type: 'any' }],
      run: (rc) => { rc.ctx.set('audit', [...(rc.ctx.get('audit') || []), JSON.stringify(rc.inputs[0])]); rc.log('info', `audit : ${JSON.stringify(rc.inputs[0])}`); return []; },
    },
  ];

  // ---------------------------------------------------------------------------
  // Le flux « Nouveau prospect » : 28 pierres.
  // ---------------------------------------------------------------------------
  const conn = (id, name, color, origin, x) => ({ id, type: 'decl.library', position: { x, y: 0 }, fields: { name, color, origin } });
  const project = {
    format: 'kantoaplo.domino', version: 2,
    editor: { id: 'automate', name: 'Flux' },
    name: 'Nouveau prospect',
    context: { événement: { nom: ' Ada Lovelace ', email: 'Ada@Example.com' }, base: ['grace@example.com'], env: { CRM_KEY: 'crm-7Q2' }, envois: [], audit: [] },
    parties: [
      {
        id: 'main', kind: 'main', name: 'Nouveau prospect',
        dominos: [
          { id: 'crm', type: 'inst.kCrm', position: { x: 334, y: 300 }, fields: { name: 'crm' }, top: [{ pip: 0, domino: { id: 'key', type: 'ctx.get', fields: { path: 'env.CRM_KEY' } } }] },
          { id: 'slk', type: 'inst.kSlack', position: { x: 760, y: 440 }, fields: { name: 'slack' } },
          { id: 'eml', type: 'inst.kMail', position: { x: 1010, y: 500 }, fields: { name: 'email' } },
          { id: 'aud', type: 'a.audit', position: { x: 110, y: 230 } },
          {
            id: 'trg', type: 'a.trigger', position: { x: 0, y: 40 },
            next: [{ pip: 0, domino: {
              id: 'ext', type: 'a.extract',
              next: [{ pip: 0, domino: {
                id: 'c1', type: 'call',
                next: [{ pip: 0, domino: {
                  id: 'si', type: 'a.if',
                  next: [
                    { pip: 0, label: 'oui', domino: { id: 'w1', type: 'a.write', fields: { tpl: 'Bon retour {nom} !' }, next: [{ pip: 0, domino: { id: 'c2', type: 'call' } }] } },
                    { pip: 1, label: 'non', domino: {
                      id: 'w2', type: 'a.write', fields: { tpl: 'Bienvenue {nom} !' },
                      next: [{ pip: 0, domino: {
                        id: 'c3', type: 'call',
                        next: [{ pip: 1, label: 'suite', domino: { id: 'c4', type: 'call' } }],
                      } }],
                    } },
                  ],
                } }],
              } }],
            } }],
          },
        ],
      },
      {
        id: 'decl', kind: 'declarations', name: 'Connecteurs',
        dominos: [conn('kCrm', 'CRM', '#3B7DDD', 'projet « CRM partagé » v2.1', 0), conn('kSlack', 'Slack', '#D9539A', '', 260), conn('kMail', 'E-mail', '#38A169', '', 520)],
      },
      {
        id: 'kCrm', kind: 'body', owner: 'kCrm', name: 'CRM',
        dominos: [
          { id: 'kc', type: 'decl.ctor', position: { x: 0, y: 0 }, fields: { params: 'clé:texte' }, next: [{ pip: 0, domino: { id: 'ks', type: 'decl.self.set', fields: { prop: 'clé' } } }] },
          { id: 'km', type: 'decl.method', position: { x: 0, y: 200 }, fields: { name: 'chercher', params: 'contact:contact', returns: 'contact', async: true, color: '#3B7DDD' }, next: [{ pip: 0, domino: { id: 'kl', type: 'a.lookup' } }] },
        ],
      },
      {
        id: 'kSlack', kind: 'body', owner: 'kSlack', name: 'Slack',
        dominos: [{ id: 'sm', type: 'decl.method', position: { x: 0, y: 0 }, fields: { name: 'publier', params: 'message:message', returns: 'message', async: true, color: '#D9539A' }, next: [{ pip: 0, domino: { id: 'sw', type: 'a.wait', fields: { ms: 300 }, next: [{ pip: 0, domino: { id: 'sp', type: 'a.post', fields: { canal: 'Slack #ventes' } } }] } }] }],
      },
      {
        id: 'kMail', kind: 'body', owner: 'kMail', name: 'E-mail',
        dominos: [{ id: 'mm', type: 'decl.method', position: { x: 0, y: 0 }, fields: { name: 'envoyer', params: 'message:message', returns: 'message', async: true, color: '#38A169' }, next: [{ pip: 0, domino: { id: 'mw', type: 'a.wait', fields: { ms: 500 }, next: [{ pip: 0, domino: { id: 'mp', type: 'a.post', fields: { canal: 'E-mail' } } }] } }] }],
      },
    ],
    wires: [
      { id: 'f1', from: { domino: 'crm', pip: 0 }, to: { domino: 'c1', pip: 0 } },
      { id: 'f2', from: { domino: 'eml', pip: 0 }, to: { domino: 'c2', pip: 0 } },
      { id: 'f3', from: { domino: 'slk', pip: 0 }, to: { domino: 'c3', pip: 0 }, blocking: false, label: 'sans attendre' },
      { id: 'f4', from: { domino: 'eml', pip: 0 }, to: { domino: 'c4', pip: 0 } },
      { id: 'f5', from: { domino: 'ext', pip: 0 }, to: { domino: 'aud', pip: 0 }, blocking: false },
    ],
  };

  // ---------------------------------------------------------------------------
  // Générateurs
  // ---------------------------------------------------------------------------
  const callOf = (g, n) => {
    const w = g.wiresInto(n, 0)[0];
    if (!w) return null;
    const inst = g.byId(w.from.domino), declId = inst && inst.type.replace(/^inst\./, '');
    const sig = D.Modules.signatureFromJSON(g.json, declId);
    const m = sig && sig.methods.filter((x) => x.public)[w.from.pip];
    return m ? { connector: sig.name, instance: (inst.fields && inst.fields.name) || sig.name, method: m.name, async: m.async, blocking: w.blocking !== false } : null;
  };
  const steps = (g, json) => {
    const main = json.parties.find((p) => p.id === 'main');
    const out = [];
    const walk = (n, after) => {
      const c = n.type === 'call' ? callOf(g, n) : null;
      const step = D.compact({ id: n.id, type: c ? 'connector.call' : n.type, name: c ? `${c.instance}.${c.method}` : n.label || undefined, parameters: c ? { connector: c.connector, action: c.method, wait: c.blocking } : n.fields, after: after.length ? after : undefined });
      out.push(step);
      for (const w of g.wiresFrom(n)) { const t = g.byId(w.to.domino); if (t && !t.type.startsWith('inst.') && t.type !== 'call') walk(t, [{ step: n.id, async: w.blocking === false }]); }
      (n.next || []).forEach((l) => walk(l.domino, [{ step: n.id, output: l.label || l.pip }]));
    };
    for (const h of main.dominos || []) if (!h.type.startsWith('inst.') && !g.wiresInto(h).length) walk(h, []);
    return out;
  };
  const workflow = new D.Generator('workflow', { label: 'Workflow JSON', extension: 'json' }).on('project', (json, g) => JSON.stringify({
    name: json.name, trigger: (json.parties[0].dominos || []).find((d) => d.type === 'a.trigger') ? 'form' : null,
    connectors: g.declarations().map((d) => D.compact({ name: d.signature.name, origin: d.node.fields && d.node.fields.origin, config: d.signature.params.map((p) => p.name), actions: d.signature.methods.map((m) => ({ name: m.name, async: m.async })) })),
    steps: steps(g, json),
  }, null, 2));
  const mermaid = new D.Generator('sequence', { label: 'Séquence Mermaid', extension: 'mmd' }).on('project', (json, g) => {
    const out = ['sequenceDiagram', '  autonumber', '  participant F as Flux'];
    for (const d of g.declarations()) out.push(`  participant ${d.signature.name.replace(/\W/g, '')} as ${d.signature.name}`);
    const main = json.parties.find((p) => p.id === 'main');
    const walk = (n, depth) => {
      if (n.type === 'call') {
        const c = callOf(g, n);
        if (c) {
          const who = c.connector.replace(/\W/g, '');
          // Bloquant : flèche pleine et réponse ; non bloquant : flèche ouverte, sans attendre.
          if (c.blocking) out.push(`  F->>+${who}: ${c.method}()${c.async ? ' (async, attendu)' : ''}`, `  ${who}-->>-F: résultat`);
          else out.push(`  F-)${who}: ${c.method}() (sans attendre)`);
        }
      } else if (n.type === 'a.if') out.push(`  Note over F: ${n.label || 'Si client connu'}`);
      for (const w of g.wiresFrom(n)) { const t = g.byId(w.to.domino); if (t && t.type === 'a.audit') out.push(`  F-)F: journal d’audit${w.blocking === false ? ' (sans attendre)' : ''}`); }
      const nx = n.next || [];
      if (nx.length > 1) {
        nx.forEach((l, i) => { out.push(`  ${i ? 'else' : 'alt'} ${l.label || `sortie ${l.pip + 1}`}`); walk(l.domino, depth + 1); });
        out.push('  end');
      } else if (nx[0]) walk(nx[0].domino, depth);
    };
    for (const h of main.dominos || []) if (h.type === 'a.trigger') walk(h, 0);
    return out.join('\n');
  });

  // ---------------------------------------------------------------------------
  // Onglet « Appels » : chaque appel de connecteur sur une ligne de temps (on voit ce qui tourne en parallèle).
  // ---------------------------------------------------------------------------
  const calls = new WeakMap();
  const callsTab = {
    id: 'calls', title: 'Appels',
    help: 'Exemple d’onglet propre au langage : les appels aux connecteurs dans le temps',
    onEvent: (ev) => ['run:end', 'run:start'].includes(ev.type),
    render: (el, insp) => {
      const list = calls.get(insp.ed) || [];
      const e = insp.esc;
      const t0 = list.length ? Math.min(...list.map((c) => c.start)) : 0;
      const end = list.length ? Math.max(...list.map((c) => c.end || c.start)) - t0 || 1 : 1;
      const envois = insp.ws.context.get('envois') || [];
      el.innerHTML = `<div class="dk-split"><div class="dk-pane"><div class="dk-toolbar"><b style="font-size:12px">Appels aux connecteurs</b><span style="color:var(--ink-3);font-size:11.5px">Lancez l’effet domino : un appel non bloquant (Slack) tourne pendant que le flux continue.</span></div>
        ${list.length ? list.map((c) => `<div class="dk-wf ok"><span class="nm">${e(c.name)}</span><span class="bar"><i style="left:${((c.start - t0) / end) * 100}%;width:${Math.max(1, (((c.end || c.start) - c.start) / end) * 100)}%"></i></span><span class="ms">${c.end ? `${Math.round(c.end - c.start)} ms` : '…'}</span></div>`).join('') : '<p class="dk-empty">Aucun appel pour l’instant.</p>'}</div>
        <div class="dk-pane"><div class="dk-toolbar"><b style="font-size:12px">Envois</b></div><pre style="margin:0;padding:10px 14px;font:12px/1.6 var(--f-mono);white-space:pre-wrap">${envois.map(e).join('\n') || '<span style="color:var(--ink-3)">rien encore</span>'}</pre></div></div>`;
    },
  };

  (D.packs = D.packs || {}).automate = D.language({
    id: 'automate', name: 'Flux', color: '#EE7D2F',
    description: 'Un outil d’automatisation : des connecteurs (dont un venu d’un autre projet), des appels asynchrones, bloquants ou non.',
    types, dominos, project, context: project.context,
    // Le vocabulaire de l'automatisation pour les faces.
    semantics: (l, r, def, base) => ({ label: { value: 'Donnée', source: 'Déclencheur', terminal: 'Action finale', step: 'Étape', free: 'Service', declaration: 'Connecteur' }[base.role] }),
    faces: {
      kinds: { déclencheur: { left: '#FBE6D4', right: '#F8D3B3' }, action: { left: '#E3EEF9', right: '#E3EEF9' }, logique: { left: '#F4E9D2', right: '#F4E9D2' } },
      legend: [
        { label: 'Déclencheur', left: '#FBE6D4', right: '#F8D3B3' },
        { label: 'Action', left: '#E3EEF9', right: '#E3EEF9' },
        { label: 'Logique', left: '#F4E9D2', right: '#F4E9D2' },
        { label: 'Connecteur', left: '#F6DCEA', right: '#EDC2DA', description: 'Teinté de sa couleur' },
      ],
    },
    rules: {
      chain: 'types', wires: true,
      list: [{ id: 'déclencheur', on: 'wire', description: 'Un déclencheur commence un flux : il ne reçoit ni n’envoie de fil.', check: (q) => (q.parent.def.kind === 'déclencheur' || q.child.def.kind === 'déclencheur' ? 'Un déclencheur commence un flux : il se colle, il ne se relie pas par un fil.' : true) }],
    },
    // Pas de classes : des connecteurs (bibliothèques) et des sous-flux (fonctions).
    modules: { title: 'Connecteurs', class: false, library: { name: 'Connecteur', uses: 'Mes connecteurs', description: 'Un service externe (ou un autre projet) : à droite, ses actions ; à gauche, sa configuration (clé d’API…).' }, function: { name: 'Sous-flux', uses: 'Mes sous-flux' } },
    generators: [workflow, mermaid],
    options: { table: 1500 },
    inspector: { tabs: [callsTab] },
    setup: (ed) => {
      ed.ws.on('run:start', () => { calls.set(ed, []); ed.ws.context.set('envois', []); ed.ws.context.set('audit', []); });
      ed.ws.on('run:call', (e) => {
        const list = calls.get(ed) || [];
        if (e.member === '#ctor') return;
        if (e.phase === 'start') list.push({ name: e.name, start: performance.now() });
        else { const c = [...list].reverse().find((x) => x.name === e.name && !x.end); if (c) c.end = performance.now(); }
        calls.set(ed, list);
      });
    },
  });
})(typeof globalThis !== 'undefined' ? globalThis : window);
