      ...cond('cond.expr', 'Condition (expression)', { expr: { kind: 'expr', label: 'Condition', default: { gte: [{ var: 'percent' }, 50] } } }, (api) => Q.text(core.exprOf(api.raw('expr'))), (f) => core.exprOf(f.expr)),
      description: 'Condition (0 | 1) écrite comme une expression : percent >= 50, réponses.domaine == "Arts" et score > 3, réponses.pays contient "France"…',
